1	import { AbsoluteFill, Audio, Img, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
2	import { FADE, FPS, Heading, ProgressBar, Subtitles } from "./Shared";
3	import type { SceneData, VideoProps } from "./types";
4	
5	export { FPS };
6	
7	export const ClassicVideo = ({ scenes }: VideoProps) => {
8	  let from = 0;
9	  return (
10	    <AbsoluteFill style={{ backgroundColor: "#000" }}>
11	      {scenes.map((scene, i) => {
12	        const frames = Math.round(scene.duration * FPS);
13	        const seq = (
14	          <Sequence key={i} from={from} durationInFrames={frames}>
15	            <Scene scene={scene} index={i} total={scenes.length} frames={frames} />
16	          </Sequence>
17	        );
18	        from += frames;
19	        return seq;
20	      })}
21	    </AbsoluteFill>
22	  );
23	};
