25	const Scene = ({ scene, index, total, frames }: {
26	  scene: SceneData; index: number; total: number; frames: number;
27	}) => {
28	  const frame = useCurrentFrame();
29	  const opacity = interpolate(frame, [0, FADE, frames - FADE, frames], [0, 1, 1, 0], {
30	    extrapolateLeft: "clamp", extrapolateRight: "clamp",
31	  });
32	  // Ken Burns: cảnh chẵn zoom vào, cảnh lẻ zoom ra
33	  const zoom = interpolate(frame, [0, frames], index % 2 === 0 ? [1, 1.12] : [1.12, 1]);
34	
35	  return (
36	    <AbsoluteFill style={{ opacity }}>
37	      <AbsoluteFill style={{ transform: `scale(${zoom})` }}>
38	        <Img src={staticFile(scene.image!)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
39	      </AbsoluteFill>
40	      {/* Lớp tối dần phía dưới để phụ đề dễ đọc */}
41	      <AbsoluteFill style={{ background: "linear-gradient(transparent 55%, rgba(0,0,0,0.75))" }} />
42	      <Heading text={scene.heading} />
43	      <Subtitles cues={scene.cues} />
44	      <ProgressBar index={index} total={total} frames={frames} />
45	      <Audio src={staticFile(scene.audio)} />
46	    </AbsoluteFill>
47	  );
48	};
