1	import { spring, useCurrentFrame, useVideoConfig } from "remotion";
2	import type { Cue } from "./types";
3	
4	export const FPS = 30;
5	export const FADE = 12; // số frame fade vào/ra mỗi cảnh
6	export const FONT = '"Segoe UI", Arial, "Helvetica Neue", sans-serif';
7	
8	export const Subtitles = ({ cues }: { cues: Cue[] }) => {
9	  const frame = useCurrentFrame();
10	  const t = frame / FPS;
11	  const cue = cues.find((c) => t >= c.start && t <= c.end + 0.15);
12	  if (!cue) return null;
13	  return (
14	    <div style={{
15	      position: "absolute", bottom: 56, left: 80, right: 80, textAlign: "center",
16	      fontFamily: FONT, fontSize: 42, fontWeight: 700, lineHeight: 1.35,
17	      textShadow: "0 2px 6px rgba(0,0,0,0.9)",
18	    }}>
19	      {cue.words.map((w, i) => {
20	        // Karaoke: từ đang đọc tô vàng, từ đã đọc trắng, từ chưa đọc xám nhạt
21	        const active = t >= w.start && t < w.end;
22	        const spoken = t >= w.end;
23	        return (
24	          <span key={i} style={{
25	            color: active ? "#ffd84d" : spoken ? "#ffffff" : "rgba(255,255,255,0.6)",
26	            display: "inline-block", marginRight: 12,
27	            transform: active ? "scale(1.08)" : "none",
28	          }}>
29	            {w.text}
30	          </span>
31	        );
32	      })}
33	    </div>
34	  );
35	};
36	
37	export const ProgressBar = ({ index, total, frames }: { index: number; total: number; frames: number }) => {
38	  const frame = useCurrentFrame();
39	  const p = (index + Math.min(frame / frames, 1)) / total;
40	  return (
41	    <div style={{ position: "absolute", left: 0, bottom: 0, height: 6, width: `${p * 100}%`, background: "#6d8cff" }} />
42	  );
43	};
44	
45	export const Heading = ({ text, enterDelay = 6 }: { text: string; enterDelay?: number }) => {
46	  const frame = useCurrentFrame();
47	  const { fps } = useVideoConfig();
48	  const enter = spring({ frame: frame - enterDelay, fps, config: { damping: 200 } });
49	  return (
50	    <div style={{
51	      position: "absolute", top: 40, left: 48,
52	      transform: `translateX(${(1 - enter) * -60}px)`, opacity: enter,
53	      padding: "10px 22px", borderRadius: 10, background: "rgba(15,18,32,0.78)",
54	      borderLeft: "6px solid #6d8cff", color: "#fff", fontFamily: FONT,
55	      fontSize: 38, fontWeight: 700, maxWidth: 900,
56	    }}>
57	      {text}
58	    </div>
59	  );
60	};
61	
62	/** Mốc thời gian (giây) từ đầu cảnh mà `keyword` được nói tới, dựa trên cues/words đã có timestamp. */
63	export const findKeywordStart = (cues: Cue[], keyword: string): number | null => {
64	  const norm = (s: string) => s.toLowerCase().replace(/[.,;:!?"'()…]/g, "");
65	  const target = norm(keyword);
66	  for (const cue of cues) {
67	    for (const w of cue.words) {
68	      if (norm(w.text).includes(target) || target.includes(norm(w.text))) {
69	        return w.start;
70	      }
71	    }
72	  }
73	  return null;
74	};
