32	const GradientScene = ({ scene, index, total, frames }: {
33	  scene: SceneData; index: number; total: number; frames: number;
34	}) => {
35	  const frame = useCurrentFrame();
36	  const opacity = interpolate(frame, [0, FADE, frames - FADE, frames], [0, 1, 1, 0], {
37	    extrapolateLeft: "clamp", extrapolateRight: "clamp",
38	  });
