55	const Keywords = ({ scene, frame }: { scene: SceneData; frame: number }) => {
56	  const { fps } = useVideoConfig();
57	  const keywords = scene.keywords ?? [];
58	  if (keywords.length === 0) return null;
59	  const t = frame / FPS;
60	
61	  return (
62	    <div style={{
63	      position: "absolute", top: 0, left: 0, right: 0, bottom: 140,
64	      display: "flex", flexDirection: "column", alignItems: "center",
