66	    }}>
67	      {keywords.map((kw, i) => {
68	        const triggerT = findKeywordStart(scene.cues, kw);
69	        const triggerFrame = triggerT != null ? triggerT * FPS : i * 20;
70	        const enter = spring({ frame: frame - triggerFrame, fps, config: { damping: 12, mass: 0.6 } });
71	        if (t * FPS < triggerFrame - 3) return null;
72	        return (
73	          <div key={i} style={{
74	            fontFamily: FONT, fontSize: 56, fontWeight: 800, color: "#fff",
75	            textShadow: "0 4px 18px rgba(0,0,0,0.35)",
76	            transform: `scale(${0.5 + enter * 0.5}) translateY(${(1 - enter) * 40}px)`,
77	            opacity: enter,
78	          }}>
79	            {kw}
80	          </div>
81	        );
82	      })}
83	    </div>
84	  );
