1	import {
2	  AbsoluteFill, Audio, Sequence, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig,
3	} from "remotion";
4	import { FPS, FADE, FONT, Heading, Subtitles, ProgressBar } from "./Shared";
5	import type { DiagramEdge, DiagramNode, SceneData, VideoProps } from "./types";
6	
7	export const FlowVideo = ({ scenes }: VideoProps) => {
8	  let from = 0;
9	  return (
10	    <AbsoluteFill style={{ backgroundColor: "#0b0e1a" }}>
11	      {scenes.map((scene, i) => {
12	        const frames = Math.round(scene.duration * FPS);
13	        const seq = (
14	          <Sequence key={i} from={from} durationInFrames={frames}>
15	            <FlowScene scene={scene} index={i} total={scenes.length} frames={frames} />
16	          </Sequence>
17	        );
18	        from += frames;
19	        return seq;
20	      })}
21	    </AbsoluteFill>
22	  );
23	};
