25	const FlowScene = ({ scene, index, total, frames }: {
26	  scene: SceneData; index: number; total: number; frames: number;
27	}) => {
28	  const frame = useCurrentFrame();
29	  const opacity = interpolate(frame, [0, FADE, frames - FADE, frames], [0, 1, 1, 0], {
30	    extrapolateLeft: "clamp", extrapolateRight: "clamp",
31	  });
32	
33	  return (
34	    <AbsoluteFill style={{ opacity }}>
35	      <AbsoluteFill style={{ background: "linear-gradient(160deg, #0b0e1a, #1a2140)" }} />
36	      <Heading text={scene.heading} />
37	      {scene.diagram ? <Diagram diagram={scene.diagram} frame={frame} /> : null}
38	      <Subtitles cues={scene.cues} />
39	      <ProgressBar index={index} total={total} frames={frames} />
40	      <Audio src={staticFile(scene.audio)} />
41	    </AbsoluteFill>
42	  );
43	};
44	
45	// Sắp các node trên một hàng ngang, cách đều nhau
46	const layoutNodes = (nodes: DiagramNode[], width: number, y: number) => {
47	  const margin = 140;
48	  const usable = width - margin * 2;
49	  return nodes.map((n, i) => ({
50	    ...n,
51	    x: nodes.length === 1 ? width / 2 : margin + (usable * i) / (nodes.length - 1),
52	    y,
53	  }));
54	};
55	
56	const Diagram = ({ diagram, frame }: { diagram: NonNullable<SceneData["diagram"]>; frame: number }) => {
57	  const { fps, width } = useVideoConfig();
58	  const y = 400;
59	  const positioned = layoutNodes(diagram.nodes, width, y);
60	  const byId = new Map(positioned.map((n) => [n.id, n]));
61	  const nodeDelay = 14; // frame giữa mỗi node xuất hiện
62	
63	  return (
64	    <svg width={width} height={720} style={{ position: "absolute", top: 0, left: 0 }}>
65	      {diagram.edges.map((edge: DiagramEdge, i: number) => {
66	        const from = byId.get(edge.from);
67	        const to = byId.get(edge.to);
68	        if (!from || !to) return null;
69	        const fromIdx = positioned.findIndex((n) => n.id === edge.from);
70	        const edgeTrigger = (fromIdx + 1) * nodeDelay + 4;
71	        const draw = spring({ frame: frame - edgeTrigger, fps, config: { damping: 200 } });
72	        const len = Math.hypot(to.x - from.x, to.y - from.y);
73	        return (
74	          <line
75	            key={i}
76	            x1={from.x} y1={from.y} x2={to.x} y2={to.y}
77	            stroke="#6d8cff" strokeWidth={4}
78	            strokeDasharray={len}
79	            strokeDashoffset={len * (1 - draw)}
80	          />
81	        );
82	      })}
83	      {positioned.map((node, i) => {
84	        const enter = spring({ frame: frame - i * nodeDelay, fps, config: { damping: 14, mass: 0.6 } });
85	        return (
86	          <g key={node.id} transform={`translate(${node.x}, ${node.y}) scale(${enter})`}>
87	            <circle r={54} fill="#1a1f35" stroke="#6d8cff" strokeWidth={3} />
88	            <text
89	              textAnchor="middle" dominantBaseline="middle" fill="#fff"
90	              fontFamily={FONT} fontSize={22} fontWeight={700}
91	            >
92	              {node.label.length > 12 ? node.label.slice(0, 11) + "…" : node.label}
93	            </text>
94	          </g>
95	        );
96	      })}
97	    </svg>
98	  );
99	};
