51	// Câu chêm hài hước bật ra giữa màn hình ở nửa đầu cảnh, giữ vài giây rồi biến mất
52	const CaptionJoke = ({ text, frames }: { text: string; frames: number }) => {
53	  const frame = useCurrentFrame();
54	  const { fps } = useVideoConfig();
55	  const triggerAt = Math.round(frames * 0.15);
56	  const holdFor = Math.min(Math.round(fps * 2.2), Math.max(frames - triggerAt - 10, fps));
57	  const local = frame - triggerAt;
58	  if (local < 0) return null;
59	
60	  const enter = spring({ frame: local, fps, config: { damping: 9, mass: 0.5, stiffness: 180 } });
61	  const fadeOut = interpolate(local, [holdFor, holdFor + 12], [1, 0], {
62	    extrapolateLeft: "clamp", extrapolateRight: "clamp",
63	  });
64	  const rotate = interpolate(enter, [0, 1], [-8, -3]);
65	
66	  return (
67	    <div style={{
68	      position: "absolute", top: "38%", left: "50%",
69	      transform: `translate(-50%, -50%) scale(${enter}) rotate(${rotate}deg)`,
70	      opacity: fadeOut,
71	      background: "#ffd84d", color: "#1a1200", padding: "16px 28px", borderRadius: 16,
72	      border: "4px solid #1a1200", fontFamily: FONT, fontSize: 46, fontWeight: 800,
73	      maxWidth: 900, textAlign: "center", boxShadow: "0 8px 0 rgba(0,0,0,0.4)",
74	    }}>
75	      {text}
76	    </div>
77	  );
78	};
