// Dữ liệu Python truyền sang qua props.json. Thời gian tính bằng giây, tương đối với đầu cảnh.
export type Word = { text: string; start: number; end: number };
export type Cue = { start: number; end: number; words: Word[] };

export type DiagramNode = { id: string; label: string };
export type DiagramEdge = { from: string; to: string };
export type Diagram = { nodes: DiagramNode[]; edges: DiagramEdge[] };

export type SceneData = {
  heading: string;
  image: string | null; // tên file trong public dir (thư mục job); null nếu template không dùng ảnh
  audio: string;
  duration: number;
  cues: Cue[];
  keywords?: string[] | null; // template "gradient": 1-3 từ khóa bay vào theo lời đọc
  stat?: string | null; // template "gradient": số liệu ngắn nổi bật
  diagram?: Diagram | null; // template "flow": sơ đồ luồng cho cảnh này
  captionJoke?: string | null; // template "meme": câu chêm hài giữa cảnh
};

export type SfxFiles = { whoosh?: string | null; pop?: string | null };

export type VideoProps = {
  title: string;
  scenes: SceneData[];
  music?: string | null; // nhạc nền (tên file trong public dir), tự giảm âm lượng khi có giọng đọc
  musicVolume?: number;
  sfx?: SfxFiles | null;
};

import { loadFont } from "@remotion/google-fonts/BeVietnamPro";
import { TransitionSeries, springTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { slide } from "@remotion/transitions/slide";
import { wipe } from "@remotion/transitions/wipe";
import React from "react";
import {
  AbsoluteFill, Audio, Img, Sequence, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import type { Cue, SceneData, VideoProps, Word } from "./types";

export const FPS = 30;
// Khung dọc 9:16 cho Shorts/Reels
export const WIDTH = 1080;
export const HEIGHT = 1920;
// Số frame hai cảnh chồng lên nhau khi chuyển cảnh; khớp SCENE_PADDING_SEC (0.4s) bên Python
// nên giọng đọc cảnh trước đã dứt trước khi cảnh sau bắt đầu.
export const TRANSITION = 12;
// Frame heading bắt đầu hiện (sau khi transition gần xong), SFX "pop" phát cùng lúc
export const HEADING_DELAY = 10;
export const ACCENT = "#6d8cff";
export const HILITE = "#ffe14d";
// Vùng an toàn: dưới ~y=1570 bị UI của Shorts/Reels (caption, nút) che nên đặt phụ đề phía trên
export const SUBTITLE_TOP = 1180;

const { fontFamily } = loadFont("normal", {
  weights: ["600", "800", "900"],
  subsets: ["vietnamese", "latin", "latin-ext"],
});
export const FONT = `"${fontFamily}", "Segoe UI", Arial, sans-serif`;

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// ---------- Khung video: chuyển cảnh, nhạc nền, SFX ----------

const timing = springTiming({ config: { damping: 200 }, durationInFrames: TRANSITION });

// Gọi như hàm (không phải component) để TransitionSeries nhận đúng kiểu phần tử con
const transitionAt = (i: number) => {
  const key = `t${i}`;
  switch (i % 4) {
    case 1: return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-right" })} timing={timing} />;
    case 2: return <TransitionSeries.Transition key={key} presentation={wipe({ direction: "from-bottom" })} timing={timing} />;
    case 3: return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-bottom" })} timing={timing} />;
    default: return <TransitionSeries.Transition key={key} presentation={fade()} timing={timing} />;
  }
};

export const sceneFrames = (scene: SceneData) => Math.max(1, Math.round(scene.duration * FPS));

type ShellProps = VideoProps & {
  background: string;
  renderScene: (scene: SceneData, index: number, frames: number) => React.ReactNode;
};

export const VideoShell = ({ scenes, music, musicVolume, sfx, background, renderScene }: ShellProps) => {
  const frames = scenes.map(sceneFrames);
  const starts: number[] = [];
  frames.reduce((acc, f) => { starts.push(acc); return acc + f; }, 0);

  // Mỗi cảnh (trừ cảnh cuối) kéo dài thêm TRANSITION frame để chồng lên cảnh sau,
  // nhờ vậy cảnh i vẫn bắt đầu đúng ở starts[i] và tổng thời lượng không đổi.
  const items: React.ReactNode[] = [];
  scenes.forEach((scene, i) => {
    if (i > 0) items.push(transitionAt(i));
    const extra = i < scenes.length - 1 ? Math.min(TRANSITION, frames[i + 1] - 1) : 0;
    items.push(
      <TransitionSeries.Sequence key={`s${i}`} durationInFrames={frames[i] + extra}>
        {renderScene(scene, i, frames[i])}
      </TransitionSeries.Sequence>,
    );
  });

  // Khoảng thời gian có giọng đọc (giây, tính từ đầu video) để giảm nhạc nền
  const speech = scenes
    .map((s, i) => s.cues.length
      ? [starts[i] / FPS + s.cues[0].start, starts[i] / FPS + s.cues[s.cues.length - 1].end] as const
      : null)
    .filter((x): x is readonly [number, number] => x !== null);

  return (
    <AbsoluteFill style={{ backgroundColor: background }}>
      <TransitionSeries>{items}</TransitionSeries>
      {music ? <BackgroundMusic src={music} volume={musicVolume ?? 0.18} speech={speech} /> : null}
      {sfx?.whoosh ? starts.slice(1).map((s, i) => (
        <Sequence key={`w${i}`} from={Math.max(0, s - 4)} durationInFrames={FPS}>
          <Audio src={staticFile(sfx.whoosh!)} volume={0.35} />
        </Sequence>
      )) : null}
      {sfx?.pop ? starts.map((s, i) => (
        <Sequence key={`p${i}`} from={s + HEADING_DELAY} durationInFrames={FPS / 2}>
          <Audio src={staticFile(sfx.pop!)} volume={0.3} />
        </Sequence>
      )) : null}
    </AbsoluteFill>
  );
};

const BackgroundMusic = ({ src, volume, speech }: {
  src: string; volume: number; speech: (readonly [number, number])[];
}) => {
  const { fps, durationInFrames: total } = useVideoConfig();
  return (
    <Audio
      src={staticFile(src)}
      loop
      volume={(f) => {
        const t = f / fps;
        // Khoảng cách tới đoạn có giọng đọc gần nhất: đang đọc thì nhạc nhỏ, khoảng lặng thì to lên
        let d = Infinity;
        for (const [a, b] of speech) {
          if (t >= a && t <= b) { d = 0; break; }
          d = Math.min(d, t < a ? a - t : t - b);
        }
        const duck = interpolate(d, [0.1, 0.6], [1, 0], CLAMP);
        const fadeInOut = interpolate(
          f, [0, fps, Math.max(fps + 1, total - fps * 1.5), Math.max(fps + 2, total)], [0, 1, 1, 0], CLAMP,
        );
        return volume * (1 - 0.6 * duck) * fadeInOut;
      }}
    />
  );
};

// ---------- Ảnh nền có chuyển động ----------

/** Ken Burns với 4 kiểu chuyển động xoay vòng theo index: zoom vào, zoom ra, pan ngang, pan dọc. */
export const KenBurns = ({ src, index, frames }: { src: string; index: number; frames: number }) => {
  const frame = useCurrentFrame();
  const p = interpolate(frame, [0, frames + TRANSITION], [0, 1], CLAMP);
  const transforms = [
    `scale(${1 + 0.15 * p})`,
    `scale(${1.15 - 0.15 * p})`,
    `scale(1.15) translateX(${4 - 8 * p}%)`,
    `scale(1.15) translateY(${4 - 8 * p}%)`,
  ];
  return (
    <AbsoluteFill style={{ transform: transforms[index % transforms.length] }}>
      <Img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    </AbsoluteFill>
  );
};

// ---------- Phụ đề kiểu TikTok ----------

type Page = { start: number; end: number; words: Word[] };

/** Chia mỗi dòng phụ đề thành các "trang" 1-3 từ, ngắt thêm sau dấu phẩy. */
const toPages = (cues: Cue[], maxWords = 3): Page[] => {
  const pages: Page[] = [];
  for (const cue of cues) {
    let current: Word[] = [];
    const flush = () => {
      if (current.length) pages.push({ start: current[0].start, end: current[current.length - 1].end, words: current });
      current = [];
    };
    for (const w of cue.words) {
      current.push(w);
      if (current.length >= maxWords || /[,;:]$/.test(w.text)) flush();
    }
    flush();
  }
  return pages;
};

export const Subtitles = ({ cues, top = SUBTITLE_TOP }: { cues: Cue[]; top?: number }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / fps;
  const pages = toPages(cues);
  let idx = -1;
  for (let i = 0; i < pages.length; i++) if (pages[i].start <= t) idx = i;
  if (idx < 0) return null;
  const page = pages[idx];
  const next = pages[idx + 1];
  // Giữ trang tới khi trang sau bắt đầu (nếu gần), tránh phụ đề nhấp nháy giữa các từ
  const until = next && next.start - page.end < 0.6 ? next.start : page.end + 0.25;
  if (t >= until) return null;

  const enter = spring({ frame: frame - page.start * fps, fps, config: { damping: 200, stiffness: 300 } });

  return (
    <div style={{
      position: "absolute", top, left: 60, right: 60,
      display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "0 24px",
      transform: `scale(${0.8 + 0.2 * enter}) translateY(${(1 - enter) * 30}px)`,
      opacity: enter,
    }}>
      {page.words.map((w, i) => {
        const active = t >= w.start && (i === page.words.length - 1 || t < page.words[i + 1].start);
        const pop = spring({ frame: frame - w.start * fps, fps, config: { damping: 10, stiffness: 260, mass: 0.5 } });
        return (
          <span key={i} style={{
            display: "inline-block", fontFamily: FONT, fontSize: 88, fontWeight: 900, lineHeight: 1.2,
            color: active ? HILITE : "#ffffff",
            WebkitTextStroke: "14px #000", paintOrder: "stroke fill",
            textShadow: "0 8px 24px rgba(0,0,0,0.55)",
            transform: `scale(${active ? 1 + 0.12 * Math.min(pop, 1.2) : 1})`,
          }}>
            {w.text}
          </span>
        );
      })}
    </div>
  );
};

// ---------- Thành phần chung ----------

export const ProgressBar = ({ index, total, frames }: { index: number; total: number; frames: number }) => {
  const frame = useCurrentFrame();
  const p = (index + Math.min(frame / frames, 1)) / total;
  return (
    <div style={{ position: "absolute", left: 0, top: 0, height: 10, width: `${p * 100}%`, background: ACCENT }} />
  );
};

export const Heading = ({ text, enterDelay = HEADING_DELAY }: { text: string; enterDelay?: number }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const enter = spring({ frame: frame - enterDelay, fps, config: { damping: 14, mass: 0.6 } });
  return (
    <div style={{ position: "absolute", top: 170, left: 60, right: 60, display: "flex", justifyContent: "center" }}>
      <div style={{
        transform: `translateY(${(1 - enter) * -50}px) scale(${0.9 + 0.1 * enter})`,
        opacity: Math.min(enter, 1),
        padding: "18px 34px", borderRadius: 24, background: "rgba(15,18,32,0.85)",
        borderBottom: `8px solid ${ACCENT}`, color: "#fff", fontFamily: FONT,
        fontSize: 58, fontWeight: 800, lineHeight: 1.25, textAlign: "center",
      }}>
        {text}
      </div>
    </div>
  );
};

/** Mốc thời gian (giây) từ đầu cảnh mà `keyword` được nói tới, dựa trên cues/words đã có timestamp. */
export const findKeywordStart = (cues: Cue[], keyword: string): number | null => {
  const norm = (s: string) => s.toLowerCase().replace(/[.,;:!?"'()…]/g, "");
  const target = norm(keyword);
  for (const cue of cues) {
    for (const w of cue.words) {
      if (norm(w.text).includes(target) || target.includes(norm(w.text))) {
        return w.start;
      }
    }
  }
  return null;
};

