1	// Dữ liệu Python truyền sang qua props.json. Thời gian tính bằng giây, tương đối với đầu cảnh.
2	export type Word = { text: string; start: number; end: number };
3	export type Cue = { start: number; end: number; words: Word[] };
4	
5	export type DiagramNode = { id: string; label: string };
6	export type DiagramEdge = { from: string; to: string };
7	export type Diagram = { nodes: DiagramNode[]; edges: DiagramEdge[] };
8	
9	export type SceneData = {
10	  heading: string;
11	  image: string | null; // tên file trong public dir (thư mục job); null nếu template không dùng ảnh
12	  audio: string;
13	  duration: number;
14	  cues: Cue[];
15	  keywords?: string[] | null; // template "gradient": 1-3 từ khóa bay vào theo lời đọc
16	  stat?: string | null; // template "gradient": số liệu ngắn nổi bật
17	  diagram?: Diagram | null; // template "flow": sơ đồ luồng cho cảnh này
18	  captionJoke?: string | null; // template "meme": câu chêm hài giữa cảnh
19	};
20	
21	export type SfxFiles = { whoosh?: string | null; pop?: string | null };
22	
23	export type VideoProps = {
24	  title: string;
25	  scenes: SceneData[];
26	  music?: string | null; // nhạc nền (tên file trong public dir), tự giảm âm lượng khi có giọng đọc
27	  musicVolume?: number;
28	  sfx?: SfxFiles | null;
29	};
30

1	import { loadFont } from "@remotion/google-fonts/BeVietnamPro";
2	import { TransitionSeries, springTiming } from "@remotion/transitions";
3	import { fade } from "@remotion/transitions/fade";
4	import { slide } from "@remotion/transitions/slide";
5	import { wipe } from "@remotion/transitions/wipe";
6	import React from "react";
7	import {
8	  AbsoluteFill, Audio, Img, Sequence, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig,
9	} from "remotion";
10	import type { Cue, SceneData, VideoProps, Word } from "./types";
11	
12	export const FPS = 30;
13	// Khung dọc 9:16 cho Shorts/Reels
14	export const WIDTH = 1080;
15	export const HEIGHT = 1920;
16	// Số frame hai cảnh chồng lên nhau khi chuyển cảnh; khớp SCENE_PADDING_SEC (0.4s) bên Python
17	// nên giọng đọc cảnh trước đã dứt trước khi cảnh sau bắt đầu.
18	export const TRANSITION = 12;
19	// Frame heading bắt đầu hiện (sau khi transition gần xong), SFX "pop" phát cùng lúc
20	export const HEADING_DELAY = 10;
21	export const ACCENT = "#6d8cff";
22	export const HILITE = "#ffe14d";
23	// Vùng an toàn: dưới ~y=1570 bị UI của Shorts/Reels (caption, nút) che nên đặt phụ đề phía trên
24	export const SUBTITLE_TOP = 1180;
25	
26	const { fontFamily } = loadFont("normal", {
27	  weights: ["600", "800", "900"],
28	  subsets: ["vietnamese", "latin", "latin-ext"],
29	});
30	export const FONT = `"${fontFamily}", "Segoe UI", Arial, sans-serif`;
31	
32	const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
33	
34	// ---------- Khung video: chuyển cảnh, nhạc nền, SFX ----------
35	
36	const timing = springTiming({ config: { damping: 200 }, durationInFrames: TRANSITION });
37	
38	// Gọi như hàm (không phải component) để TransitionSeries nhận đúng kiểu phần tử con
39	const transitionAt = (i: number) => {
40	  const key = `t${i}`;
41	  switch (i % 4) {
42	    case 1: return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-right" })} timing={timing} />;
43	    case 2: return <TransitionSeries.Transition key={key} presentation={wipe({ direction: "from-bottom" })} timing={timing} />;
44	    case 3: return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-bottom" })} timing={timing} />;
45	    default: return <TransitionSeries.Transition key={key} presentation={fade()} timing={timing} />;
46	  }
47	};
48	
49	export const sceneFrames = (scene: SceneData) => Math.max(1, Math.round(scene.duration * FPS));
50	
51	type ShellProps = VideoProps & {
52	  background: string;
53	  renderScene: (scene: SceneData, index: number, frames: number) => React.ReactNode;
54	};
55	
56	export const VideoShell = ({ scenes, music, musicVolume, sfx, background, renderScene }: ShellProps) => {
57	  const frames = scenes.map(sceneFrames);
58	  const starts: number[] = [];
59	  frames.reduce((acc, f) => { starts.push(acc); return acc + f; }, 0);
60	
61	  // Mỗi cảnh (trừ cảnh cuối) kéo dài thêm TRANSITION frame để chồng lên cảnh sau,
62	  // nhờ vậy cảnh i vẫn bắt đầu đúng ở starts[i] và tổng thời lượng không đổi.
63	  const items: React.ReactNode[] = [];
64	  scenes.forEach((scene, i) => {
65	    if (i > 0) items.push(transitionAt(i));
66	    const extra = i < scenes.length - 1 ? Math.min(TRANSITION, frames[i + 1] - 1) : 0;
67	    items.push(
68	      <TransitionSeries.Sequence key={`s${i}`} durationInFrames={frames[i] + extra}>
69	        {renderScene(scene, i, frames[i])}
70	      </TransitionSeries.Sequence>,
71	    );
72	  });
73	
74	  // Khoảng thời gian có giọng đọc (giây, tính từ đầu video) để giảm nhạc nền
75	  const speech = scenes
76	    .map((s, i) => s.cues.length
77	      ? [starts[i] / FPS + s.cues[0].start, starts[i] / FPS + s.cues[s.cues.length - 1].end] as const
78	      : null)
79	    .filter((x): x is readonly [number, number] => x !== null);
80	
81	  return (
82	    <AbsoluteFill style={{ backgroundColor: background }}>
83	      <TransitionSeries>{items}</TransitionSeries>
84	      {music ? <BackgroundMusic src={music} volume={musicVolume ?? 0.18} speech={speech} /> : null}
85	      {sfx?.whoosh ? starts.slice(1).map((s, i) => (
86	        <Sequence key={`w${i}`} from={Math.max(0, s - 4)} durationInFrames={FPS}>
87	          <Audio src={staticFile(sfx.whoosh!)} volume={0.35} />
88	        </Sequence>
89	      )) : null}
90	      {sfx?.pop ? starts.map((s, i) => (
91	        <Sequence key={`p${i}`} from={s + HEADING_DELAY} durationInFrames={FPS / 2}>
92	          <Audio src={staticFile(sfx.pop!)} volume={0.3} />
93	        </Sequence>
94	      )) : null}
95	    </AbsoluteFill>
96	  );
97	};
98	
99	const BackgroundMusic = ({ src, volume, speech }: {
100	  src: string; volume: number; speech: (readonly [number, number])[];
101	}) => {
102	  const { fps, durationInFrames: total } = useVideoConfig();
103	  return (
104	    <Audio
105	      src={staticFile(src)}
106	      loop
107	      volume={(f) => {
108	        const t = f / fps;
109	        // Khoảng cách tới đoạn có giọng đọc gần nhất: đang đọc thì nhạc nhỏ, khoảng lặng thì to lên
110	        let d = Infinity;
111	        for (const [a, b] of speech) {
112	          if (t >= a && t <= b) { d = 0; break; }
113	          d = Math.min(d, t < a ? a - t : t - b);
114	        }
115	        const duck = interpolate(d, [0.1, 0.6], [1, 0], CLAMP);
116	        const fadeInOut = interpolate(
117	          f, [0, fps, Math.max(fps + 1, total - fps * 1.5), Math.max(fps + 2, total)], [0, 1, 1, 0], CLAMP,
118	        );
119	        return volume * (1 - 0.6 * duck) * fadeInOut;
120	      }}
121	    />
122	  );
123	};
124	
125	// ---------- Ảnh nền có chuyển động ----------
126	
127	/** Ken Burns với 4 kiểu chuyển động xoay vòng theo index: zoom vào, zoom ra, pan ngang, pan dọc. */
128	export const KenBurns = ({ src, index, frames }: { src: string; index: number; frames: number }) => {
129	  const frame = useCurrentFrame();
130	  const p = interpolate(frame, [0, frames + TRANSITION], [0, 1], CLAMP);
131	  const transforms = [
132	    `scale(${1 + 0.15 * p})`,
133	    `scale(${1.15 - 0.15 * p})`,
134	    `scale(1.15) translateX(${4 - 8 * p}%)`,
135	    `scale(1.15) translateY(${4 - 8 * p}%)`,
136	  ];
137	  return (
138	    <AbsoluteFill style={{ transform: transforms[index % transforms.length] }}>
139	      <Img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
140	    </AbsoluteFill>
141	  );
142	};
143	
144	// ---------- Phụ đề kiểu TikTok ----------
145	
146	type Page = { start: number; end: number; words: Word[] };
147	
148	/** Chia mỗi dòng phụ đề thành các "trang" 1-3 từ, ngắt thêm sau dấu phẩy. */
149	const toPages = (cues: Cue[], maxWords = 3): Page[] => {
150	  const pages: Page[] = [];
151	  for (const cue of cues) {
152	    let current: Word[] = [];
153	    const flush = () => {
154	      if (current.length) pages.push({ start: current[0].start, end: current[current.length - 1].end, words: current });
155	      current = [];
156	    };
157	    for (const w of cue.words) {
158	      current.push(w);
159	      if (current.length >= maxWords || /[,;:]$/.test(w.text)) flush();
160	    }
161	    flush();
162	  }
163	  return pages;
164	};
165	
166	export const Subtitles = ({ cues, top = SUBTITLE_TOP }: { cues: Cue[]; top?: number }) => {
167	  const frame = useCurrentFrame();
168	  const { fps } = useVideoConfig();
169	  const t = frame / fps;
170	  const pages = toPages(cues);
171	  let idx = -1;
172	  for (let i = 0; i < pages.length; i++) if (pages[i].start <= t) idx = i;
173	  if (idx < 0) return null;
174	  const page = pages[idx];
175	  const next = pages[idx + 1];
176	  // Giữ trang tới khi trang sau bắt đầu (nếu gần), tránh phụ đề nhấp nháy giữa các từ
177	  const until = next && next.start - page.end < 0.6 ? next.start : page.end + 0.25;
178	  if (t >= until) return null;
179	
180	  const enter = spring({ frame: frame - page.start * fps, fps, config: { damping: 200, stiffness: 300 } });
181	
182	  return (
183	    <div style={{
184	      position: "absolute", top, left: 60, right: 60,
185	      display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "0 24px",
186	      transform: `scale(${0.8 + 0.2 * enter}) translateY(${(1 - enter) * 30}px)`,
187	      opacity: enter,
188	    }}>
189	      {page.words.map((w, i) => {
190	        const active = t >= w.start && (i === page.words.length - 1 || t < page.words[i + 1].start);
191	        const pop = spring({ frame: frame - w.start * fps, fps, config: { damping: 10, stiffness: 260, mass: 0.5 } });
192	        return (
193	          <span key={i} style={{
194	            display: "inline-block", fontFamily: FONT, fontSize: 88, fontWeight: 900, lineHeight: 1.2,
195	            color: active ? HILITE : "#ffffff",
196	            WebkitTextStroke: "14px #000", paintOrder: "stroke fill",
197	            textShadow: "0 8px 24px rgba(0,0,0,0.55)",
198	            transform: `scale(${active ? 1 + 0.12 * Math.min(pop, 1.2) : 1})`,
199	          }}>
200	            {w.text}
201	          </span>
202	        );
203	      })}
204	    </div>
205	  );
206	};
207	
208	// ---------- Thành phần chung ----------
209	
210	export const ProgressBar = ({ index, total, frames }: { index: number; total: number; frames: number }) => {
211	  const frame = useCurrentFrame();
212	  const p = (index + Math.min(frame / frames, 1)) / total;
213	  return (
214	    <div style={{ position: "absolute", left: 0, top: 0, height: 10, width: `${p * 100}%`, background: ACCENT }} />
215	  );
216	};
217	
218	export const Heading = ({ text, enterDelay = HEADING_DELAY }: { text: string; enterDelay?: number }) => {
219	  const frame = useCurrentFrame();
220	  const { fps } = useVideoConfig();
221	  const enter = spring({ frame: frame - enterDelay, fps, config: { damping: 14, mass: 0.6 } });
222	  return (
223	    <div style={{ position: "absolute", top: 170, left: 60, right: 60, display: "flex", justifyContent: "center" }}>
224	      <div style={{
