226	        opacity: Math.min(enter, 1),
227	        padding: "18px 34px", borderRadius: 24, background: "rgba(15,18,32,0.85)",
228	        borderBottom: `8px solid ${ACCENT}`, color: "#fff", fontFamily: FONT,
229	        fontSize: 58, fontWeight: 800, lineHeight: 1.25, textAlign: "center",
230	      }}>
231	        {text}
232	      </div>
233	    </div>
234	  );
235	};
236	
