import { AbsoluteFill, Audio, staticFile } from "remotion";
import { FPS, Heading, KenBurns, ProgressBar, Subtitles, VideoShell } from "./Shared";
import type { SceneData, VideoProps } from "./types";

export { FPS };

export const ClassicVideo = (props: VideoProps) => (
  <VideoShell
    {...props}
    background="#000"
    renderScene={(scene, i, frames) => (
      <Scene scene={scene} index={i} total={props.scenes.length} frames={frames} />
    )}
  />
);

const Scene = ({ scene, index, total, frames }: {
  scene: SceneData; index: number; total: number; frames: number;
}) => (
  <AbsoluteFill style={{ backgroundColor: "#000" }}>
    {scene.image ? <KenBurns src={scene.image} index={index} frames={frames} /> : null}
    {/* Tối phía trên cho heading và vùng giữa-dưới cho phụ đề */}
    <AbsoluteFill style={{
      background: "linear-gradient(rgba(0,0,0,0.55), transparent 22%, transparent 50%, rgba(0,0,0,0.7) 80%)",
    }} />
    <Heading text={scene.heading} />
    <Subtitles cues={scene.cues} />
    <ProgressBar index={index} total={total} frames={frames} />
    <Audio src={staticFile(scene.audio)} />
  </AbsoluteFill>
);

import {
  AbsoluteFill, Audio, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import { FONT, Heading, KenBurns, ProgressBar, Subtitles, VideoShell } from "./Shared";
import type { SceneData, VideoProps } from "./types";

export const MemeVideo = (props: VideoProps) => (
  <VideoShell
    {...props}
    background="#000"
    renderScene={(scene, i, frames) => (
      <MemeScene scene={scene} index={i} total={props.scenes.length} frames={frames} />
    )}
  />
);

const MemeScene = ({ scene, index, total, frames }: {
  scene: SceneData; index: number; total: number; frames: number;
}) => (
  <AbsoluteFill style={{ backgroundColor: "#000" }}>
    {scene.image ? <KenBurns src={scene.image} index={index} frames={frames} /> : null}
    <AbsoluteFill style={{
      background: "linear-gradient(rgba(0,0,0,0.55), transparent 22%, transparent 50%, rgba(0,0,0,0.7) 80%)",
    }} />
    <Heading text={scene.heading} />
    {scene.captionJoke ? <CaptionJoke text={scene.captionJoke} frames={frames} /> : null}
    <Subtitles cues={scene.cues} />
    <ProgressBar index={index} total={total} frames={frames} />
    <Audio src={staticFile(scene.audio)} />
  </AbsoluteFill>
);

// Câu chêm hài hước bật ra giữa màn hình ở nửa đầu cảnh, giữ vài giây rồi biến mất
const CaptionJoke = ({ text, frames }: { text: string; frames: number }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const triggerAt = Math.round(frames * 0.15);
  const holdFor = Math.min(Math.round(fps * 2.2), Math.max(frames - triggerAt - 10, fps));
  const local = frame - triggerAt;
  if (local < 0) return null;

  const enter = spring({ frame: local, fps, config: { damping: 9, mass: 0.5, stiffness: 180 } });
  const fadeOut = interpolate(local, [holdFor, holdFor + 12], [1, 0], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });
  const rotate = interpolate(enter, [0, 1], [-8, -3]);

  return (
    <div style={{
      position: "absolute", top: "42%", left: "50%",
      transform: `translate(-50%, -50%) scale(${enter}) rotate(${rotate}deg)`,
      opacity: fadeOut,
      background: "#ffd84d", color: "#1a1200", padding: "24px 36px", borderRadius: 20,
      border: "6px solid #1a1200", fontFamily: FONT, fontSize: 64, fontWeight: 900,
      width: 880, textAlign: "center", lineHeight: 1.2, boxShadow: "0 12px 0 rgba(0,0,0,0.4)",
    }}>
      {text}
    </div>
  );
};

import {
  AbsoluteFill, Audio, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import { FONT, HILITE, Heading, ProgressBar, Subtitles, VideoShell, findKeywordStart } from "./Shared";
import type { SceneData, VideoProps } from "./types";

const PALETTES = [
  ["#1e3c72", "#7b2ff7"],
  ["#0f2027", "#2c5364"],
  ["#4b134f", "#c94b4b"],
  ["#134e5e", "#71b280"],
];

export const GradientVideo = (props: VideoProps) => (
  <VideoShell
    {...props}
    background="#000"
    renderScene={(scene, i, frames) => (
      <GradientScene scene={scene} index={i} total={props.scenes.length} frames={frames} />
    )}
  />
);

const GradientScene = ({ scene, index, total, frames }: {
  scene: SceneData; index: number; total: number; frames: number;
}) => {
  const frame = useCurrentFrame();
  const [from, to] = PALETTES[index % PALETTES.length];
  const angle = interpolate(frame, [0, frames], [0, 45], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ background: `linear-gradient(${135 + angle}deg, ${from}, ${to})` }} />
      <Heading text={scene.heading} />
      <Keywords scene={scene} frame={frame} />
      <Stat scene={scene} />
      <Subtitles cues={scene.cues} top={1320} />
      <ProgressBar index={index} total={total} frames={frames} />
      <Audio src={staticFile(scene.audio)} />
    </AbsoluteFill>
  );
};

const Keywords = ({ scene, frame }: { scene: SceneData; frame: number }) => {
  const { fps } = useVideoConfig();
  const keywords = scene.keywords ?? [];
  if (keywords.length === 0) return null;

  return (
    <div style={{
      position: "absolute", top: 560, left: 60, right: 60, height: 520,
      display: "flex", flexDirection: "column", alignItems: "center",
      justifyContent: "center", gap: 28,
    }}>
      {keywords.map((kw, i) => {
        const triggerT = findKeywordStart(scene.cues, kw);
        const triggerFrame = triggerT != null ? triggerT * fps : i * 20;
        if (frame < triggerFrame - 3) return null;
        const enter = spring({ frame: frame - triggerFrame, fps, config: { damping: 12, mass: 0.6 } });
        return (
          <div key={i} style={{
            fontFamily: FONT, fontSize: 96, fontWeight: 900, color: "#fff", textAlign: "center",
            lineHeight: 1.1, textShadow: "0 6px 24px rgba(0,0,0,0.4)",
            transform: `scale(${0.5 + enter * 0.5}) translateY(${(1 - enter) * 50}px)`,
            opacity: Math.min(enter, 1),
          }}>
            {kw}
          </div>
        );
      })}
    </div>
  );
};

const Stat = ({ scene }: { scene: SceneData }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  if (!scene.stat) return null;
  const enter = spring({ frame: frame - 14, fps, config: { damping: 12, mass: 0.6 } });
  return (
    <div style={{
      position: "absolute", top: 360, left: 0, right: 0, textAlign: "center",
      fontFamily: FONT, fontSize: 150, fontWeight: 900, color: HILITE,
      textShadow: "0 8px 28px rgba(0,0,0,0.45)",
      transform: `scale(${enter})`, opacity: Math.min(enter, 1),
    }}>
      {scene.stat}
    </div>
  );
};

import {
  AbsoluteFill, Audio, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import { ACCENT, FONT, Heading, ProgressBar, Subtitles, VideoShell } from "./Shared";
import type { DiagramEdge, DiagramNode, SceneData, VideoProps } from "./types";

export const FlowVideo = (props: VideoProps) => (
  <VideoShell
    {...props}
    background="#0b0e1a"
    renderScene={(scene, i, frames) => (
      <FlowScene scene={scene} index={i} total={props.scenes.length} frames={frames} />
    )}
  />
);

const FlowScene = ({ scene, index, total, frames }: {
  scene: SceneData; index: number; total: number; frames: number;
}) => {
  const frame = useCurrentFrame();
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ background: "linear-gradient(160deg, #0b0e1a, #1a2140)" }} />
      <Heading text={scene.heading} />
      {scene.diagram ? <Diagram diagram={scene.diagram} frame={frame} /> : null}
      <Subtitles cues={scene.cues} top={1360} />
      <ProgressBar index={index} total={total} frames={frames} />
      <Audio src={staticFile(scene.audio)} />
    </AbsoluteFill>
  );
};

// Khung dọc: xếp các node theo cột, cách đều trong vùng giữa heading và phụ đề
const TOP = 420;
const BOTTOM = 1300;
const BOX_W = 620;
const BOX_H = 120;

const layoutNodes = (nodes: DiagramNode[], width: number) => {
  const step = nodes.length > 1 ? (BOTTOM - TOP - BOX_H) / (nodes.length - 1) : 0;
  return nodes.map((n, i) => ({
    ...n,
    x: width / 2,
    y: nodes.length === 1 ? (TOP + BOTTOM) / 2 : TOP + BOX_H / 2 + step * i,
  }));
};

const Diagram = ({ diagram, frame }: { diagram: NonNullable<SceneData["diagram"]>; frame: number }) => {
  const { fps, width, height } = useVideoConfig();
  const positioned = layoutNodes(diagram.nodes, width);
  const byId = new Map(positioned.map((n) => [n.id, n]));
  const nodeDelay = 14; // frame giữa mỗi node xuất hiện

  return (
    <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
      <defs>
        <marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto">
          <path d="M0,0 L10,5 L0,10 z" fill={ACCENT} />
        </marker>
      </defs>
      {diagram.edges.map((edge: DiagramEdge, i: number) => {
        const from = byId.get(edge.from);
        const to = byId.get(edge.to);
        if (!from || !to) return null;
        const fromIdx = positioned.findIndex((n) => n.id === edge.from);
        const draw = spring({ frame: frame - ((fromIdx + 1) * nodeDelay + 4), fps, config: { damping: 200 } });
        // Nối từ cạnh dưới node trước tới cạnh trên node sau
        const dir = to.y >= from.y ? 1 : -1;
        const y1 = from.y + dir * BOX_H / 2;
        const y2 = to.y - dir * (BOX_H / 2 + 6);
        const len = Math.abs(y2 - y1) + Math.abs(to.x - from.x);
        if (draw <= 0.01) return null;
        return (
          <line
            key={i}
            x1={from.x} y1={y1} x2={to.x} y2={y2}
            stroke={ACCENT} strokeWidth={6}
            strokeDasharray={len}
            strokeDashoffset={len * (1 - draw)}
            markerEnd={draw > 0.9 ? "url(#arrow)" : undefined}
          />
        );
      })}
      {positioned.map((node, i) => {
        const enter = spring({ frame: frame - i * nodeDelay, fps, config: { damping: 14, mass: 0.6 } });
        const label = node.label.length > 24 ? node.label.slice(0, 23) + "…" : node.label;
        return (
          <g key={node.id} transform={`translate(${node.x}, ${node.y}) scale(${enter})`}>
            <rect x={-BOX_W / 2} y={-BOX_H / 2} width={BOX_W} height={BOX_H} rx={28}
              fill="#1a1f35" stroke={ACCENT} strokeWidth={4} />
            <text
              textAnchor="middle" dominantBaseline="middle" fill="#fff"
              fontFamily={FONT} fontSize={48} fontWeight={800}
            >
              {label}
            </text>
          </g>
        );
      })}
    </svg>
  );
};

import { Composition } from "remotion";
import { ClassicVideo } from "./ClassicVideo";
import { GradientVideo } from "./GradientVideo";
import { FlowVideo } from "./FlowVideo";
import { MemeVideo } from "./MemeVideo";
import { FPS, HEIGHT, WIDTH, sceneFrames } from "./Shared";
import type { VideoProps } from "./types";

const defaultProps: VideoProps = { title: "Xem trước", scenes: [] };

// Transition chồng cảnh nhưng mỗi cảnh (trừ cảnh cuối) được kéo dài bù lại, nên tổng không đổi
const calculateMetadata = ({ props }: { props: VideoProps }) => {
  const total = props.scenes.reduce((s, sc) => s + sceneFrames(sc), 0);
  return { durationInFrames: Math.max(total, 1) };
};

const COMPOSITIONS = [
  { id: "ClassicVideo", component: ClassicVideo },
  { id: "GradientVideo", component: GradientVideo },
  { id: "FlowVideo", component: FlowVideo },
  { id: "MemeVideo", component: MemeVideo },
];

export const RemotionRoot = () => (
  <>
    {COMPOSITIONS.map(({ id, component }) => (
      <Composition
        key={id}
        id={id}
        component={component}
        fps={FPS}
        width={WIDTH}
        height={HEIGHT}
        durationInFrames={FPS * 5}
        defaultProps={defaultProps}
        calculateMetadata={calculateMetadata}
      />
    ))}
  </>
);

