"""Lấy ảnh minh họa từ Gemini (qua CLIProxyAPI) hoặc Pollinations, dự phòng bằng ảnh tự vẽ."""

import base64
import textwrap
from pathlib import Path
from urllib.parse import quote

import httpx
from PIL import Image, ImageDraw, ImageFont

from .config import (
    FONT_CANDIDATES, GEMINI_IMAGE_API_KEY, GEMINI_IMAGE_BASE_URL, GEMINI_IMAGE_MODEL,
    IMAGE_BACKEND, VIDEO_H, VIDEO_W,
)

POLLINATIONS_URL = "https://image.pollinations.ai/prompt/{prompt}"
STYLE_SUFFIX = ", digital illustration, clean, vibrant, high detail, no text"
MEME_STYLE_SUFFIX = ", funny cartoon meme style, exaggerated expressions, bold outlines, vibrant colors, no text"
PORTRAIT_SUFFIX = ", vertical 9:16 composition, main subject centered"

Size = tuple[int, int]


def fetch_image(prompt: str, out_path: Path, seed: int, retries: int = 2,
                style_suffix: str | None = None, size: Size = (VIDEO_W, VIDEO_H)) -> bool:
    suffix = style_suffix if style_suffix is not None else STYLE_SUFFIX
    if size[1] > size[0]:
        suffix += PORTRAIT_SUFFIX
    if IMAGE_BACKEND == "gemini" and _fetch_gemini(prompt, out_path, retries, suffix, size):
        return True
    return _fetch_pollinations(prompt, out_path, seed, retries, suffix, size)


def _aspect_ratio(size: Size) -> str:
    return "9:16" if size[1] > size[0] else "16:9"


def _fetch_gemini(prompt: str, out_path: Path, retries: int, suffix: str, size: Size) -> bool:
    if not GEMINI_IMAGE_API_KEY:
        return False
    url = f"{GEMINI_IMAGE_BASE_URL.rstrip('/')}/v1beta/models/{GEMINI_IMAGE_MODEL}:generateContent"
    headers = {"Authorization": f"Bearer {GEMINI_IMAGE_API_KEY}"}
    body = {
        "contents": [{"role": "user", "parts": [{"text": prompt + suffix}]}],
        "generationConfig": {
            "responseModalities": ["IMAGE"],
            "imageConfig": {"aspectRatio": _aspect_ratio(size)},
        },
    }
    for attempt in range(retries + 1):
        try:
            r = httpx.post(url, headers=headers, json=body, timeout=120)
            if r.status_code == 400 and "imageConfig" in body["generationConfig"]:
                # Proxy/model cũ có thể không nhận imageConfig: bỏ đi, ảnh sẽ được cắt lại theo khung
                body["generationConfig"].pop("imageConfig")
                continue
            if r.status_code != 200:
                continue
            data = _extract_inline_image(r.json())
            if data is None:
                continue
            out_path.write_bytes(data)
            Image.open(out_path).verify()  # đảm bảo không phải file hỏng
            _fit_to(out_path, size)
            return True
        except (httpx.HTTPError, OSError, KeyError, ValueError):
            pass
    return False


def _extract_inline_image(response: dict) -> bytes | None:
    for candidate in response.get("candidates", []):
        for part in candidate.get("content", {}).get("parts", []):
            inline = part.get("inlineData")
            if inline and inline.get("data"):
                return base64.b64decode(inline["data"])
    return None


def _crop_to_ratio(img: Image.Image, size: Size) -> Image.Image:
    w, h = img.size
    target_ratio = size[0] / size[1]
    if w / h > target_ratio:
        new_w = int(h * target_ratio)
        left = (w - new_w) // 2
        return img.crop((left, 0, left + new_w, h))
    new_h = int(w / target_ratio)
    top = (h - new_h) // 2
    return img.crop((0, top, w, top + new_h))


def _fit_to(path: Path, size: Size) -> None:
    img = _crop_to_ratio(Image.open(path).convert("RGB"), size)
    img.resize(size, Image.LANCZOS).save(path, quality=92)


def _fetch_pollinations(prompt: str, out_path: Path, seed: int, retries: int, suffix: str,
                        size: Size) -> bool:
    url = POLLINATIONS_URL.format(prompt=quote(prompt + suffix, safe=""))
    params = {"width": size[0], "height": size[1], "nologo": "true", "seed": seed}
    for _ in range(retries + 1):
        try:
            r = httpx.get(url, params=params, timeout=120, follow_redirects=True)
            if r.status_code == 200 and r.headers.get("content-type", "").startswith("image/"):
                out_path.write_bytes(r.content)
                Image.open(out_path).verify()  # đảm bảo không phải file hỏng
                _strip_watermark(out_path, size)
                return True
        except (httpx.HTTPError, OSError):
            pass
    return False


def _strip_watermark(path: Path, size: Size, crop_ratio: float = 0.07) -> None:
    """Pollinations chèn logo ở góc dưới phải (nologo chỉ có hiệu lực với tài khoản đăng ký).
    Cắt bỏ dải dưới cùng rồi cắt/phóng lại cho đủ khung."""
    img = Image.open(path).convert("RGB")
    w, h = img.size
    img = _crop_to_ratio(img.crop((0, 0, w, int(h * (1 - crop_ratio)))), size)
    img.resize(size, Image.LANCZOS).save(path, quality=92)


def placeholder_image(heading: str, out_path: Path, index: int,
                      size: Size = (VIDEO_W, VIDEO_H)) -> None:
    width, height = size
    palettes = [((32, 58, 110), (88, 40, 120)), ((20, 90, 90), (30, 50, 110)),
                ((110, 50, 40), (60, 30, 90)), ((40, 80, 50), (20, 50, 90))]
    top, bottom = palettes[index % len(palettes)]
    img = Image.new("RGB", size)
    draw = ImageDraw.Draw(img)
    for y in range(height):
        t = y / height
        draw.line([(0, y), (width, y)],
                  fill=tuple(int(a + (b - a) * t) for a, b in zip(top, bottom)))

    font_path = next((p for p in FONT_CANDIDATES if p.exists()), None)
    font = ImageFont.truetype(str(font_path), 64) if font_path else ImageFont.load_default()
    # Khung dọc hẹp hơn nên ngắt dòng sớm hơn
    text = "\n".join(textwrap.wrap(heading, 28 if width > height else 18))
    box = draw.multiline_textbbox((0, 0), text, font=font, align="center")
    x = (width - (box[2] - box[0])) / 2
    y = (height - (box[3] - box[1])) / 2 - 60
    draw.multiline_text((x, y), text, font=font, fill="white", align="center")
    img.save(out_path, quality=92)

"""Nhạc nền và SFX cho bản Remotion: chọn nhạc từ MUSIC_DIR, tự sinh SFX bằng ffmpeg nếu chưa có."""

import random
import shutil
from pathlib import Path

from .config import MUSIC_DIR, SFX_DIR
from .render import run_ffmpeg

MUSIC_EXTS = {".mp3", ".m4a", ".wav", ".ogg", ".aac"}

# Âm thanh tổng hợp bằng filter của ffmpeg, không cần tải file ngoài
SFX_RECIPES = {
    # Tiếng gió lướt: pink noise lọc thông thấp, to dần rồi nhỏ dần
    "whoosh.wav": ["-f", "lavfi", "-i", "anoisesrc=d=0.6:c=pink:a=0.5",
                   "-af", "highpass=f=300,lowpass=f=3500,afade=t=in:d=0.35,afade=t=out:st=0.35:d=0.25"],
    # Tiếng "pop": sóng sin tụt tần số nhanh, tắt dần theo hàm mũ
    "pop.wav": ["-f", "lavfi", "-i", "aevalsrc='0.8*sin(2*PI*(900-2500*t)*t)*exp(-28*t)':d=0.16:s=44100"],
}


def ensure_sfx() -> dict[str, Path]:
    """Trả về {"whoosh": path, "pop": path}; file nào sinh lỗi thì bỏ qua (video vẫn render được)."""
    SFX_DIR.mkdir(parents=True, exist_ok=True)
    result: dict[str, Path] = {}
    for name, args in SFX_RECIPES.items():
        path = SFX_DIR / name
        if not path.exists():
            try:
                run_ffmpeg([*args, "-ac", "2", "-ar", "44100", name], cwd=SFX_DIR)
            except RuntimeError:
                continue
        result[path.stem] = path
    return result


def pick_music(seed: str | None = None) -> Path | None:
    if not MUSIC_DIR.is_dir():
        return None
    tracks = sorted(p for p in MUSIC_DIR.iterdir() if p.suffix.lower() in MUSIC_EXTS)
    if not tracks:
        return None
    return random.Random(seed).choice(tracks)


def stage_into(work_dir: Path, src: Path, name: str) -> str:
    """Copy file vào thư mục job (public dir của Remotion), trả về tên file để truyền qua props."""
    dest = work_dir / f"{name}{src.suffix.lower()}"
    shutil.copy(src, dest)
    return dest.name

