"""B-roll: mỗi câu thoại một đoạn video stock dọc từ Pexels, đổi hình theo mốc thời gian câu."""

from dataclasses import dataclass
from pathlib import Path

import httpx

from .config import PEXELS_API_KEY
from .tts import Cue

SEARCH_URL = "https://api.pexels.com/videos/search"
SENTENCE_END = (".", "!", "?", "…")
# Beat ngắn hơn mức này bị gộp vào beat trước; dài hơn MAX thì tách đôi (cùng truy vấn, clip khác)
MIN_BEAT_SEC = 1.6
MAX_BEAT_SEC = 5.0
MAX_DOWNLOAD_BYTES = 80 * 1024 * 1024


@dataclass
class Beat:
    start: float  # giây, tương đối với đầu cảnh
    end: float
    query: str
    video: Path | None = None
    video_duration: float | None = None  # 0 = không rõ độ dài


def sentence_starts(cues: list[Cue]) -> list[float]:
    """Mốc bắt đầu từng câu, dựa vào dấu câu gốc mà words_to_cues đã gắn lại cho từng từ."""
    starts: list[float] = []
    new_sentence = True
    for cue in cues:
        for w in cue.words:
            if new_sentence:
                starts.append(w.start)
                new_sentence = False
            if w.text.rstrip("\"')»”").endswith(SENTENCE_END):
                new_sentence = True
    return starts


def plan_beats(cues: list[Cue], queries: list[str], scene_end: float) -> list[Beat]:
    """Ghép truy vấn thứ i với câu thứ i; beat đầu luôn bắt đầu từ 0 để không bị khung trống."""
    beats: list[Beat] = []
    for start, query in zip(sentence_starts(cues), queries):
        query = query.strip()
        if not query or (beats and start - beats[-1].start < MIN_BEAT_SEC):
            continue
        beats.append(Beat(0.0 if not beats else start, 0.0, query))
    for a, b in zip(beats, beats[1:]):
        a.end = b.start
    if beats:
        beats[-1].end = scene_end

    result: list[Beat] = []
    for b in beats:
        if b.end - b.start > MAX_BEAT_SEC:
            mid = (b.start + b.end) / 2
            result += [Beat(b.start, mid, b.query), Beat(mid, b.end, b.query)]
        else:
            result.append(b)
    return result


def fetch_broll(query: str, out: Path, min_duration: float, used: set[int],
                size: tuple[int, int]) -> float | None:
    """Tải clip phù hợp nhất (chưa dùng trong video này). Trả về độ dài clip, None nếu không có."""
    if not PEXELS_API_KEY:
        return None
    try:
        r = httpx.get(SEARCH_URL, params={"query": query, "orientation": "portrait", "per_page": 15},
                      headers={"Authorization": PEXELS_API_KEY}, timeout=30)
        r.raise_for_status()
        videos = r.json().get("videos", [])
    except (httpx.HTTPError, ValueError):
        return None

    videos = [v for v in videos if v.get("id") not in used]
    # Giữ thứ tự liên quan của Pexels, chỉ đẩy clip quá ngắn (phải lặp lại) xuống cuối
    videos.sort(key=lambda v: (v.get("duration") or 0) < min_duration)
    for v in videos:
        f = _pick_file(v.get("video_files", []), size)
        if f and _download(f["link"], out):
            used.add(v["id"])
            return float(v.get("duration") or 0)
    return None


def _pick_file(files: list[dict], size: tuple[int, int]) -> dict | None:
    mp4 = [f for f in files if f.get("file_type") == "video/mp4" and f.get("link")
           and f.get("width") and f.get("height")]
    portrait = [f for f in mp4 if f["height"] > f["width"]] or mp4
    if not portrait:
        return None
    # Độ phân giải gần khung video nhất: đủ nét mà không tải file 4K nặng
    return min(portrait, key=lambda f: abs(f["height"] - size[1]))


def _download(url: str, out: Path) -> bool:
    tmp = out.with_suffix(".part")
    try:
        with httpx.stream("GET", url, timeout=120, follow_redirects=True) as r:
            if r.status_code != 200:
                return False
            written = 0
            with open(tmp, "wb") as fh:
                for chunk in r.iter_bytes():
                    written += len(chunk)
                    if written > MAX_DOWNLOAD_BYTES:
                        raise ValueError("clip quá lớn")
                    fh.write(chunk)
        tmp.replace(out)
        return True
