import { AbsoluteFill, Audio, Loop, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { FPS, Heading, KenBurns, ProgressBar, Subtitles, TRANSITION, VideoShell } from "./Shared";
import type { BrollBeat, SceneData, VideoProps } from "./types";

export { FPS };

export const ClassicVideo = (props: VideoProps) => (
  <VideoShell
    {...props}
    background="#000"
    renderScene={(scene, i, frames) => (
      <Scene scene={scene} index={i} total={props.scenes.length} frames={frames} />
    )}
  />
);

const Scene = ({ scene, index, total, frames }: {
  scene: SceneData; index: number; total: number; frames: number;
}) => (
  <AbsoluteFill style={{ backgroundColor: "#000" }}>
    {/* Ảnh AI nằm dưới cùng, lộ ra ở những beat không tìm được b-roll */}
    {scene.image ? <KenBurns src={scene.image} index={index} frames={frames} /> : null}
    {(scene.broll ?? []).map((beat, j, all) => (
      <BrollClip key={j} beat={beat} index={index + j} last={j === all.length - 1} sceneFrames={frames} />
    ))}
    {/* Tối phía trên cho heading và vùng giữa-dưới cho phụ đề */}
    <AbsoluteFill style={{
      background: "linear-gradient(rgba(0,0,0,0.55), transparent 22%, transparent 50%, rgba(0,0,0,0.7) 80%)",
    }} />
    <Heading text={scene.heading} />
    <Subtitles cues={scene.cues} />
    <ProgressBar index={index} total={total} frames={frames} />
    <Audio src={staticFile(scene.audio)} />
  </AbsoluteFill>
);

/** Một đoạn b-roll: cắt thẳng (hard cut) giữa các beat, zoom nhẹ cho đỡ tĩnh. */
const BrollClip = ({ beat, index, last, sceneFrames }: {
  beat: BrollBeat; index: number; last: boolean; sceneFrames: number;
}) => {
  const from = Math.round(beat.start * FPS);
  // Beat cuối kéo thêm TRANSITION frame để phủ phần cảnh chồng lên cảnh sau
  const end = last ? sceneFrames + TRANSITION : Math.round(beat.end * FPS);
  const duration = Math.max(1, end - from);
  const clipFrames = Math.round(beat.videoDuration * FPS);

  const video = (
    <OffthreadVideo
      src={staticFile(beat.video)}
      muted
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  );
  return (
    <Sequence from={from} durationInFrames={duration}>
      <Zoom frames={duration} index={index}>
        {/* Clip ngắn hơn beat thì lặp lại; không rõ độ dài thì phát một lần */}
        {clipFrames > 0 && clipFrames < duration ? <Loop durationInFrames={clipFrames}>{video}</Loop> : video}
      </Zoom>
    </Sequence>
  );
};

const Zoom = ({ frames, index, children }: { frames: number; index: number; children: React.ReactNode }) => {
  const frame = useCurrentFrame();
  const p = interpolate(frame, [0, frames], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const scale = index % 2 === 0 ? 1 + 0.08 * p : 1.08 - 0.08 * p;
  return <AbsoluteFill style={{ transform: `scale(${scale})` }}>{children}</AbsoluteFill>;
};

