34	const TOP = 420;
35	const BOTTOM = 1300;
36	const BOX_W = 620;
37	const BOX_H = 120;
38	
39	const layoutNodes = (nodes: DiagramNode[], width: number) => {
40	  const step = nodes.length > 1 ? (BOTTOM - TOP - BOX_H) / (nodes.length - 1) : 0;
41	  return nodes.map((n, i) => ({
42	    ...n,
43	    x: width / 2,
44	    y: nodes.length === 1 ? (TOP + BOTTOM) / 2 : TOP + BOX_H / 2 + step * i,
45	  }));
46	};
47	
48	const Diagram = ({ diagram, frame }: { diagram: NonNullable<SceneData["diagram"]>; frame: number }) => {
49	  const { fps, width, height } = useVideoConfig();
50	  const positioned = layoutNodes(diagram.nodes, width);
51	  const byId = new Map(positioned.map((n) => [n.id, n]));
