86	        const label = node.label.length > 24 ? node.label.slice(0, 23) + "…" : node.label;
87	        return (
88	          <g key={node.id} transform={`translate(${node.x}, ${node.y}) scale(${enter})`}>
89	            <rect x={-BOX_W / 2} y={-BOX_H / 2} width={BOX_W} height={BOX_H} rx={28}
90	              fill="#1a1f35" stroke={ACCENT} strokeWidth={4} />
91	            <text
92	              textAnchor="middle" dominantBaseline="middle" fill="#fff"
93	              fontFamily={FONT} fontSize={48} fontWeight={800}
94	            >
95	              {label}
96	            </text>
97	          </g>
98	        );
99	      })}
100	    </svg>
101	  );
102	};
