import { useContext } from "react";
import {
  AbsoluteFill, Audio, Sequence, interpolate, random, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import { ACCENT, CLAMP, FONT, HILITE, SfxContext, findKeywordStart } from "./Shared";
import type { Cue } from "./types";

// ---------- Nền động: aurora + vệt sáng quét + hạt bokeh + lưới chấm ----------

export type Palette = { base: [string, string]; glow: [string, string, string] };

export const PALETTES: Palette[] = [
  { base: ["#0b1240", "#2a0f5c"], glow: ["#6d8cff", "#b44dff", "#28d7ff"] },
  { base: ["#03141c", "#0b3342"], glow: ["#1fe3c2", "#2c8cff", "#7bffb0"] },
  { base: ["#22081f", "#4a0f28"], glow: ["#ff4d8d", "#ff9f43", "#c04dff"] },
  { base: ["#071f16", "#0f2f40"], glow: ["#4dffa6", "#2cc9ff", "#d4ff4d"] },
];

export const DARK_PALETTE: Palette = { base: ["#070a16", "#141a38"], glow: ["#3d5bff", "#7a3dff", "#1fb8ff"] };

type BgOptions = { sweep?: boolean; particles?: boolean; grid?: boolean; intensity?: number };

/**
 * Nền chuyển động liên tục. Chỉ dùng radial/linear-gradient (không dùng filter blur)
 * để render nhanh. Mọi chuyển động tính theo frame nên kết quả render ổn định.
 */
export const AnimatedBackground = ({ palette, seed = 0, sweep = true, particles = true, grid = false, intensity = 1 }:
  { palette: Palette; seed?: number } & BgOptions) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const t = frame / fps + seed * 7.3; // lệch pha giữa các cảnh cho đỡ giống nhau
  const [c1, c2] = palette.base;

  // 3 đốm sáng lớn trôi theo quỹ đạo Lissajous, tạo cảm giác màu "chảy"
  const blobs = palette.glow.map((color, i) => {
    const x = width * (0.5 + 0.38 * Math.sin(t * (0.35 + i * 0.12) + i * 2.1));
    const y = height * (0.45 + 0.3 * Math.cos(t * (0.27 + i * 0.09) + i * 1.3));
    const size = 1150 + 180 * Math.sin(t * 0.5 + i);
    return `radial-gradient(circle ${size / 2}px at ${x}px ${y}px, ${color}${alpha(0.55 * intensity)}, transparent 70%)`;
  });

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <AbsoluteFill style={{ background: `linear-gradient(${150 + 25 * Math.sin(t * 0.3)}deg, ${c1}, ${c2})` }} />
      <AbsoluteFill style={{ background: blobs.join(","), filter: `hue-rotate(${18 * Math.sin(t * 0.25)}deg)` }} />
      {grid ? <DotGrid t={t} /> : null}
      {particles ? <Bokeh t={t} seed={seed} /> : null}
      {sweep ? <LightSweep t={t} /> : null}
      {/* Vignette giữ mắt người xem ở giữa khung và làm chữ nổi hơn */}
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, transparent 50%, rgba(0,0,0,0.55))" }} />
    </AbsoluteFill>
  );
};

const alpha = (a: number) => Math.round(Math.max(0, Math.min(1, a)) * 255).toString(16).padStart(2, "0");

/** Vệt sáng chéo quét ngang màn hình, lặp mỗi 4.5 giây (kiểu ánh đèn lướt qua mặt kính). */
const LightSweep = ({ t }: { t: number }) => {
  const { width } = useVideoConfig();
  const period = 4.5;
  const p = (t % period) / period;
  const x = interpolate(p, [0, 0.55, 1], [-width, width * 1.2, width * 1.2]);
  return (
    <AbsoluteFill style={{ pointerEvents: "none", mixBlendMode: "screen" }}>
      <div style={{
        position: "absolute", top: -400, bottom: -400, width: 520, left: x,
        transform: "rotate(18deg)",
        background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.10) 40%, rgba(255,255,255,0.22) 50%, rgba(255,255,255,0.10) 60%, transparent)",
      }} />
    </AbsoluteFill>
  );
};

/** Hạt sáng nhỏ bay lên, nhấp nháy. Vị trí sinh bằng random(seed) nên mỗi lần render đều giống nhau. */
const Bokeh = ({ t, seed }: { t: number; seed: number }) => {
  const { width, height } = useVideoConfig();
  const dots = Array.from({ length: 28 }, (_, i) => {
    const r = (k: string) => random(`bokeh-${seed}-${i}-${k}`);
    const size = 6 + r("s") * 22;
    const speed = 30 + r("v") * 70; // px/giây
    const y = ((r("y") * (height + 200) - t * speed) % (height + 200) + height + 200) % (height + 200) - 100;
    const x = r("x") * width + 30 * Math.sin(t * (0.5 + r("w")) + i);
    const twinkle = 0.25 + 0.45 * (0.5 + 0.5 * Math.sin(t * (1 + r("f") * 2) + i));
    return (
      <div key={i} style={{
        position: "absolute", left: x, top: y, width: size, height: size, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(255,255,255,0.95), rgba(255,255,255,0) 70%)",
        opacity: twinkle,
      }} />
    );
  });
  return <AbsoluteFill>{dots}</AbsoluteFill>;
};

/** Lưới chấm mờ trôi chậm, hợp với phong cách "công nghệ" của template flow. */
const DotGrid = ({ t }: { t: number }) => (
  <AbsoluteFill style={{
    backgroundImage: "radial-gradient(rgba(255,255,255,0.10) 2px, transparent 2.5px)",
    backgroundSize: "64px 64px",
    backgroundPosition: `${(t * 12) % 64}px ${(t * 20) % 64}px`,
  }} />
);

// ---------- Chip từ khóa dạng nút bấm ----------

const CHIP_COLORS = [ACCENT, HILITE, "#4dffc3", "#ff6fb1"];

/**
 * Mỗi từ khóa là một "nút" bật ra đúng lúc được đọc tới: nảy vào, nhấn xuống như bị bấm,
 * có vòng sóng lan ra, vệt sáng lướt qua mặt nút và tiếng "pop". Nút đã hiện thì giữ lại tới hết cảnh.
 */
export const KeywordChips = ({ keywords, cues, frames, top, fontSize = 60 }: {
  keywords?: string[] | null; cues: Cue[]; frames: number; top: number; fontSize?: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const sfx = useContext(SfxContext);
  const list = (keywords ?? []).filter((k) => k.trim()).slice(0, 4);
  if (!list.length) return null;

  // Không tìm thấy từ khóa trong lời đọc thì rải đều trong cảnh
  const triggers = list.map((kw, i) => {
    const s = findKeywordStart(cues, kw);
    return s != null ? Math.round(s * fps) : Math.round((frames * (i + 1)) / (list.length + 1));
  });

  return (
    <>
      <div style={{
        position: "absolute", top, left: 50, right: 50,
        display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "28px 26px",
      }}>
        {list.map((kw, i) => (
          <Chip key={i} text={kw} local={frame - triggers[i]} color={CHIP_COLORS[i % CHIP_COLORS.length]} fontSize={fontSize} />
        ))}
      </div>
      {sfx?.pop ? triggers.map((f, i) => (
        <Sequence key={i} from={Math.max(0, f)} durationInFrames={Math.round(fps / 2)}>
          <Audio src={staticFile(sfx.pop!)} volume={0.4} />
        </Sequence>
      )) : null}
    </>
  );
};

const Chip = ({ text, local, color, fontSize }: { text: string; local: number; color: string; fontSize: number }) => {
  const { fps } = useVideoConfig();
  // Vẫn render khi chưa tới lượt (opacity 0) để các nút không nhảy vị trí khi nút mới xuất hiện
  const visible = local >= 0;
  const enter = visible ? spring({ frame: local, fps, config: { damping: 11, mass: 0.6, stiffness: 170 } }) : 0;
  const press = interpolate(local, [9, 13, 20], [1, 0.9, 1], CLAMP); // nhấn xuống rồi bật lên
  const shine = interpolate(local, [6, 24], [-120, 220], CLAMP); // vệt sáng lướt qua mặt nút (%)
  const ripple = interpolate(local, [11, 32], [0, 1], CLAMP);
  // Sáng rực lúc vừa được đọc, sau ~1 giây dịu lại thành nút "kính" nhưng vẫn phát sáng nhẹ
  const hot = interpolate(local, [0, 6, fps * 1.1, fps * 1.6], [0, 1, 1, 0], CLAMP);
  const breathe = 0.5 + 0.5 * Math.sin(local / 9);

  return (
    <div style={{
      position: "relative", opacity: Math.min(enter, 1),
      transform: `translateY(${(1 - enter) * 60}px) scale(${(0.6 + 0.4 * enter) * press})`,
    }}>
      {visible && ripple > 0 && ripple < 1 ? (
        <div style={{
          position: "absolute", inset: 0, borderRadius: 999, border: `4px solid ${color}`,
          transform: `scale(${1 + 0.45 * ripple})`, opacity: 1 - ripple,
        }} />
      ) : null}
      <div style={{
        position: "relative", overflow: "hidden", display: "flex", alignItems: "center", gap: 18,
        padding: "20px 40px 22px 30px", borderRadius: 999,
        background: `linear-gradient(135deg, rgba(12,16,34,${0.78 - 0.25 * hot}), rgba(12,16,34,0.62)), ${color}`,
        border: `4px solid ${color}`,
        boxShadow: `0 10px 30px rgba(0,0,0,0.45), 0 0 ${18 + 30 * hot + 10 * breathe}px ${color}${alpha(0.55 + 0.3 * hot)}`,
        fontFamily: FONT, fontSize, fontWeight: 800, color: "#fff", lineHeight: 1.15, whiteSpace: "nowrap",
      }}>
        <span style={{
          width: fontSize * 0.42, height: fontSize * 0.42, borderRadius: "50%", flexShrink: 0,
          background: color, boxShadow: `0 0 ${12 + 12 * breathe}px ${color}`,
        }} />
        {text}
        <span style={{
          position: "absolute", top: 0, bottom: 0, left: `${shine}%`, width: "45%",
          transform: "skewX(-20deg)",
          background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.45), transparent)",
        }} />
      </div>
    </div>
  );
};

