import {
  AbsoluteFill, Audio, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import { AnimatedBackground, KeywordChips, PALETTES } from "./Effects";
import { FONT, HILITE, Heading, ProgressBar, Subtitles, VideoShell } from "./Shared";
import type { SceneData, VideoProps } from "./types";

export const GradientVideo = (props: VideoProps) => (
  <VideoShell
    {...props}
    background="#000"
    renderScene={(scene, i, frames) => (
      <GradientScene scene={scene} index={i} total={props.scenes.length} frames={frames} />
    )}
  />
);

const GradientScene = ({ scene, index, total, frames }: {
  scene: SceneData; index: number; total: number; frames: number;
}) => (
  <AbsoluteFill>
    <AnimatedBackground palette={PALETTES[index % PALETTES.length]} seed={index} />
    <Heading text={scene.heading} />
    <Stat scene={scene} />
    <KeywordChips keywords={scene.keywords} cues={scene.cues} frames={frames}
      top={scene.stat ? 640 : 560} fontSize={64} />
    <Subtitles cues={scene.cues} top={1320} />
    <ProgressBar index={index} total={total} frames={frames} />
    <Audio src={staticFile(scene.audio)} />
  </AbsoluteFill>
);

const Stat = ({ scene }: { scene: SceneData }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  if (!scene.stat) return null;
  const enter = spring({ frame: frame - 14, fps, config: { damping: 12, mass: 0.6 } });
  // Nhịp "thở" nhẹ để con số không đứng yên
  const pulse = 1 + 0.03 * Math.sin(frame / 8);
  return (
    <div style={{
      position: "absolute", top: 360, left: 0, right: 0, textAlign: "center",
      fontFamily: FONT, fontSize: 150, fontWeight: 900, color: HILITE,
      textShadow: `0 8px 28px rgba(0,0,0,0.45), 0 0 ${30 + 20 * Math.sin(frame / 8)}px ${HILITE}88`,
      transform: `scale(${enter * pulse})`, opacity: Math.min(enter, 1),
    }}>
      {scene.stat}
    </div>
  );
};

