1	import { loadFont } from "@remotion/google-fonts/BeVietnamPro";
2	import { TransitionSeries, springTiming } from "@remotion/transitions";
3	import { fade } from "@remotion/transitions/fade";
4	import { slide } from "@remotion/transitions/slide";
5	import { wipe } from "@remotion/transitions/wipe";
6	import React from "react";
7	import {
8	  AbsoluteFill, Audio, Img, Sequence, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig,
9	} from "remotion";
10	import type { Cue, SceneData, SfxFiles, VideoProps, Word } from "./types";
11	
12	export const FPS = 30;
13	// Khung dọc 9:16 cho Shorts/Reels
14	export const WIDTH = 1080;
15	export const HEIGHT = 1920;
16	// Số frame hai cảnh chồng lên nhau khi chuyển cảnh; khớp SCENE_PADDING_SEC (0.4s) bên Python
17	// nên giọng đọc cảnh trước đã dứt trước khi cảnh sau bắt đầu.
18	export const TRANSITION = 12;
19	// Frame heading bắt đầu hiện (sau khi transition gần xong), SFX "pop" phát cùng lúc
20	export const HEADING_DELAY = 10;
21	export const ACCENT = "#6d8cff";
22	export const HILITE = "#ffe14d";
23	// Vùng an toàn: dưới ~y=1570 bị UI của Shorts/Reels (caption, nút) che nên đặt phụ đề phía trên
24	export const SUBTITLE_TOP = 1180;
25	
26	const { fontFamily } = loadFont("normal", {
27	  weights: ["600", "800", "900"],
28	  subsets: ["vietnamese", "latin", "latin-ext"],
29	});
30	export const FONT = `"${fontFamily}", "Segoe UI", Arial, sans-serif`;
31	
32	export const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
33	
34	// Cho các thành phần bên trong cảnh (vd chip từ khóa) tự phát SFX mà không phải truyền props qua nhiều lớp
35	export const SfxContext = React.createContext<SfxFiles | null>(null);
36	
37	// ---------- Khung video: chuyển cảnh, nhạc nền, SFX ----------
38	
39	const timing = springTiming({ config: { damping: 200 }, durationInFrames: TRANSITION });
40	
41	// Gọi như hàm (không phải component) để TransitionSeries nhận đúng kiểu phần tử con
42	const transitionAt = (i: number) => {
43	  const key = `t${i}`;
44	  switch (i % 4) {
45	    case 1: return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-right" })} timing={timing} />;
46	    case 2: return <TransitionSeries.Transition key={key} presentation={wipe({ direction: "from-bottom" })} timing={timing} />;
47	    case 3: return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-bottom" })} timing={timing} />;
48	    default: return <TransitionSeries.Transition key={key} presentation={fade()} timing={timing} />;
49	  }
50	};
51	
52	export const sceneFrames = (scene: SceneData) => Math.max(1, Math.round(scene.duration * FPS));
53	
54	type ShellProps = VideoProps & {
55	  background: string;
56	  renderScene: (scene: SceneData, index: number, frames: number) => React.ReactNode;
57	};
58	
59	export const VideoShell = ({ scenes, music, musicVolume, sfx, background, renderScene }: ShellProps) => {
60	  const frames = scenes.map(sceneFrames);
61	  const starts: number[] = [];
62	  frames.reduce((acc, f) => { starts.push(acc); return acc + f; }, 0);
63	
64	  // Mỗi cảnh (trừ cảnh cuối) kéo dài thêm TRANSITION frame để chồng lên cảnh sau,
65	  // nhờ vậy cảnh i vẫn bắt đầu đúng ở starts[i] và tổng thời lượng không đổi.
66	  const items: React.ReactNode[] = [];
67	  scenes.forEach((scene, i) => {
68	    if (i > 0) items.push(transitionAt(i));
69	    const extra = i < scenes.length - 1 ? Math.min(TRANSITION, frames[i + 1] - 1) : 0;
70	    items.push(
71	      <TransitionSeries.Sequence key={`s${i}`} durationInFrames={frames[i] + extra}>
72	        {renderScene(scene, i, frames[i])}
73	      </TransitionSeries.Sequence>,
74	    );
75	  });
76	
77	  // Khoảng thời gian có giọng đọc (giây, tính từ đầu video) để giảm nhạc nền
78	  const speech = scenes
79	    .map((s, i) => s.cues.length
80	      ? [starts[i] / FPS + s.cues[0].start, starts[i] / FPS + s.cues[s.cues.length - 1].end] as const
81	      : null)
82	    .filter((x): x is readonly [number, number] => x !== null);
83	
84	  return (
85	    <SfxContext.Provider value={sfx ?? null}>
86	    <AbsoluteFill style={{ backgroundColor: background }}>
87	      <TransitionSeries>{items}</TransitionSeries>
88	      {music ? <BackgroundMusic src={music} volume={musicVolume ?? 0.18} speech={speech} /> : null}
89	      {sfx?.whoosh ? starts.slice(1).map((s, i) => (
90	        <Sequence key={`w${i}`} from={Math.max(0, s - 4)} durationInFrames={FPS}>
91	          <Audio src={staticFile(sfx.whoosh!)} volume={0.35} />
92	        </Sequence>
93	      )) : null}
94	      {sfx?.pop ? starts.map((s, i) => (
95	        <Sequence key={`p${i}`} from={s + HEADING_DELAY} durationInFrames={FPS / 2}>
96	          <Audio src={staticFile(sfx.pop!)} volume={0.3} />
97	        </Sequence>
98	      )) : null}
99	    </AbsoluteFill>
100	    </SfxContext.Provider>
101	  );
102	};
103	
104	const BackgroundMusic = ({ src, volume, speech }: {
105	  src: string; volume: number; speech: (readonly [number, number])[];
106	}) => {
107	  const { fps, durationInFrames: total } = useVideoConfig();
108	  return (
109	    <Audio
110	      src={staticFile(src)}
111	      loop
112	      volume={(f) => {
113	        const t = f / fps;
114	        // Khoảng cách tới đoạn có giọng đọc gần nhất: đang đọc thì nhạc nhỏ, khoảng lặng thì to lên
115	        let d = Infinity;
116	        for (const [a, b] of speech) {
117	          if (t >= a && t <= b) { d = 0; break; }
118	          d = Math.min(d, t < a ? a - t : t - b);
119	        }
120	        const duck = interpolate(d, [0.1, 0.6], [1, 0], CLAMP);
121	        const fadeInOut = interpolate(
122	          f, [0, fps, Math.max(fps + 1, total - fps * 1.5), Math.max(fps + 2, total)], [0, 1, 1, 0], CLAMP,
123	        );
124	        return volume * (1 - 0.6 * duck) * fadeInOut;
125	      }}
126	    />
127	  );
128	};
129	
130	// ---------- Ảnh nền có chuyển động ----------
131	
132	/** Ken Burns với 4 kiểu chuyển động xoay vòng theo index: zoom vào, zoom ra, pan ngang, pan dọc. */
133	export const KenBurns = ({ src, index, frames }: { src: string; index: number; frames: number }) => {
134	  const frame = useCurrentFrame();
135	  const p = interpolate(frame, [0, frames + TRANSITION], [0, 1], CLAMP);
136	  const transforms = [
137	    `scale(${1 + 0.15 * p})`,
138	    `scale(${1.15 - 0.15 * p})`,
139	    `scale(1.15) translateX(${4 - 8 * p}%)`,
140	    `scale(1.15) translateY(${4 - 8 * p}%)`,
141	  ];
142	  return (
143	    <AbsoluteFill style={{ transform: transforms[index % transforms.length] }}>
144	      <Img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
145	    </AbsoluteFill>
146	  );
147	};
148	
149	// ---------- Phụ đề kiểu TikTok ----------
150	
151	type Page = { start: number; end: number; words: Word[] };
152	
153	/** Chia mỗi dòng phụ đề thành các "trang" 1-3 từ, ngắt thêm sau dấu phẩy. */
154	const toPages = (cues: Cue[], maxWords = 3): Page[] => {
155	  const pages: Page[] = [];
156	  for (const cue of cues) {
157	    let current: Word[] = [];
158	    const flush = () => {
159	      if (current.length) pages.push({ start: current[0].start, end: current[current.length - 1].end, words: current });
160	      current = [];
161	    };
162	    for (const w of cue.words) {
163	      current.push(w);
164	      if (current.length >= maxWords || /[,;:]$/.test(w.text)) flush();
165	    }
166	    flush();
167	  }
168	  return pages;
169	};
170	
171	export const Subtitles = ({ cues, top = SUBTITLE_TOP }: { cues: Cue[]; top?: number }) => {
172	  const frame = useCurrentFrame();
173	  const { fps } = useVideoConfig();
174	  const t = frame / fps;
175	  const pages = toPages(cues);
176	  let idx = -1;
177	  for (let i = 0; i < pages.length; i++) if (pages[i].start <= t) idx = i;
178	  if (idx < 0) return null;
179	  const page = pages[idx];
180	  const next = pages[idx + 1];
181	  // Giữ trang tới khi trang sau bắt đầu (nếu gần), tránh phụ đề nhấp nháy giữa các từ
182	  const until = next && next.start - page.end < 0.6 ? next.start : page.end + 0.25;
183	  if (t >= until) return null;
184	
185	  const enter = spring({ frame: frame - page.start * fps, fps, config: { damping: 200, stiffness: 300 } });
186	
187	  return (
188	    <div style={{
189	      position: "absolute", top, left: 60, right: 60,
190	      display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "0 34px",
191	      transform: `scale(${0.8 + 0.2 * enter}) translateY(${(1 - enter) * 30}px)`,
192	      opacity: enter,
193	    }}>
194	      {page.words.map((w, i) => {
195	        const active = t >= w.start && (i === page.words.length - 1 || t < page.words[i + 1].start);
196	        const pop = spring({ frame: frame - w.start * fps, fps, config: { damping: 10, stiffness: 260, mass: 0.5 } });
197	        return (
198	          <span key={i} style={{
199	            display: "inline-block", fontFamily: FONT, fontSize: 88, fontWeight: 900, lineHeight: 1.2,
200	            color: active ? HILITE : "#ffffff",
201	            WebkitTextStroke: "14px #000", paintOrder: "stroke fill",
202	            textShadow: "0 8px 24px rgba(0,0,0,0.55)",
203	            transform: `scale(${active ? 1 + 0.12 * Math.min(pop, 1.2) : 1})`,
204	          }}>
205	            {w.text}
206	          </span>
207	        );
208	      })}
209	    </div>
210	  );
