229	      <div style={{
230	        transform: `translateY(${(1 - enter) * -50}px) scale(${0.9 + 0.1 * enter})`,
231	        opacity: Math.min(enter, 1),
232	        padding: "18px 34px", borderRadius: 24, background: "rgba(15,18,32,0.85)",
233	        borderBottom: `8px solid ${ACCENT}`, color: "#fff", fontFamily: FONT,
234	        fontSize: 58, fontWeight: 800, lineHeight: 1.25, textAlign: "center",
235	      }}>
236	        {text}
237	      </div>
