242	const normWord = (s: string) => s.normalize("NFC").toLowerCase().replace(/[.,;:!?"'()…“”«»]/g, "");
243	
244	/**
245	 * Mốc thời gian (giây) từ đầu cảnh mà `keyword` được nói tới. Ưu tiên khớp nguyên cụm từ liên tiếp
246	 * (vd "hệ thần kinh"), nếu không có thì khớp chữ dài nhất của cụm, tránh dính vào chữ phổ biến như "là".
247	 */
248	export const findKeywordStart = (cues: Cue[], keyword: string): number | null => {
249	  const words = cues.flatMap((c) => c.words);
250	  const spoken = words.map((w) => normWord(w.text));
251	  const target = keyword.split(/\s+/).map(normWord).filter(Boolean);
252	  if (!target.length) return null;
253	  for (let i = 0; i + target.length <= spoken.length; i++) {
254	    if (target.every((tw, k) => spoken[i + k] === tw)) return words[i].start;
255	  }
256	  const longest = [...target].sort((a, b) => b.length - a.length)[0];
257	  if (longest.length < 3) return null;
258	  const j = spoken.indexOf(longest);
259	  return j >= 0 ? words[j].start : null;
260	};
