import { loadFont } from "@remotion/google-fonts/BeVietnamPro";
import React, { useContext } from "react";
import { AbsoluteFill, Img, interpolate, random, spring, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import type { Cue, SceneData, SfxFiles, Theme, Word } from "./types";

export const FPS = 30;
// Khung dọc 9:16 cho Shorts/Reels
export const WIDTH = 1080;
export const HEIGHT = 1920;
// Số frame hai cảnh chồng lên nhau khi chuyển cảnh; khớp SCENE_PADDING_SEC (0.4s) bên Python
// nên giọng đọc cảnh trước đã dứt trước khi cảnh sau bắt đầu.
export const TRANSITION = 12;
// Intro (tiêu đề) và outro (kêu gọi follow), tính bằng frame. INTRO phải khớp INTRO_SEC trong app/config.py
export const INTRO = 36;
export const OUTRO = 90;
// Frame heading bắt đầu hiện (sau khi transition gần xong), SFX "pop" phát cùng lúc
export const HEADING_DELAY = 10;
export const ACCENT = "#6d8cff";
export const HILITE = "#ffe14d";
export const KEYWORD_COLOR = "#4dffc3";
// Vùng an toàn: dưới ~y=1570 bị UI của Shorts/Reels (caption, nút) che nên đặt phụ đề phía trên
export const SUBTITLE_TOP = 1180;

const { fontFamily } = loadFont("normal", {
  weights: ["600", "800", "900"],
  subsets: ["vietnamese", "latin", "latin-ext"],
});
// Font emoji hệ thống (Windows: Segoe UI Emoji) cho icon cạnh chip từ khóa
export const FONT = `"${fontFamily}", "Segoe UI", Arial, "Segoe UI Emoji", "Noto Color Emoji", sans-serif`;

export const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// Cho các thành phần bên trong cảnh (vd chip từ khóa) tự phát SFX mà không phải truyền props qua nhiều lớp
export const SfxContext = React.createContext<SfxFiles | null>(null);
// Nhóm chủ đề của video: quyết định kiểu hạt nền và hiệu ứng glitch
export const ThemeContext = React.createContext<Theme>("general");

export const sceneFrames = (scene: SceneData) => Math.max(1, Math.round(scene.duration * FPS));

// Transition chồng cảnh nhưng mỗi đoạn (trừ đoạn cuối) được kéo dài bù lại, nên tổng không đổi
export const totalFrames = (scenes: SceneData[]) =>
  INTRO + scenes.reduce((s, sc) => s + sceneFrames(sc), 0) + OUTRO;

// ---------- Ảnh nền có chuyển động ----------

/** Ken Burns với 4 kiểu chuyển động xoay vòng theo index: zoom vào, zoom ra, pan ngang, pan dọc. */
export const KenBurns = ({ src, index, frames }: { src: string; index: number; frames: number }) => {
  const frame = useCurrentFrame();
  const p = interpolate(frame, [0, frames + TRANSITION], [0, 1], CLAMP);
  const transforms = [
    `scale(${1 + 0.15 * p})`,
    `scale(${1.15 - 0.15 * p})`,
    `scale(1.15) translateX(${4 - 8 * p}%)`,
    `scale(1.15) translateY(${4 - 8 * p}%)`,
  ];
  return (
    <AbsoluteFill style={{ transform: transforms[index % transforms.length] }}>
      <Img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    </AbsoluteFill>
  );
};

// ---------- Phụ đề kiểu TikTok ----------

type Page = { start: number; end: number; words: Word[] };

/** Chia mỗi dòng phụ đề thành các "trang" 1-3 từ, ngắt thêm sau dấu phẩy. */
const toPages = (cues: Cue[], maxWords = 3): Page[] => {
  const pages: Page[] = [];
  for (const cue of cues) {
    let current: Word[] = [];
    const flush = () => {
      if (current.length) pages.push({ start: current[0].start, end: current[current.length - 1].end, words: current });
      current = [];
    };
    for (const w of cue.words) {
      current.push(w);
      if (current.length >= maxWords || /[,;:]$/.test(w.text)) flush();
    }
    flush();
  }
  return pages;
};

export const Subtitles = ({ cues, keywords, top = SUBTITLE_TOP }: {
  cues: Cue[]; keywords?: string[] | null; top?: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / fps;
  const pages = toPages(cues);
  let idx = -1;
  for (let i = 0; i < pages.length; i++) if (pages[i].start <= t) idx = i;
  if (idx < 0) return null;
  const page = pages[idx];
  const next = pages[idx + 1];
  // Giữ trang tới khi trang sau bắt đầu (nếu gần), tránh phụ đề nhấp nháy giữa các từ
  const until = next && next.start - page.end < 0.6 ? next.start : page.end + 0.25;
  if (t >= until) return null;

  const emphasized = keywordWords(cues, keywords);
  const enter = spring({ frame: frame - page.start * fps, fps, config: { damping: 200, stiffness: 300 } });

  return (
    <div style={{
      position: "absolute", top, left: 60, right: 60,
      display: "flex", flexWrap: "wrap", justifyContent: "center", alignItems: "baseline", gap: "0 34px",
      transform: `scale(${0.8 + 0.2 * enter}) translateY(${(1 - enter) * 30}px)`,
      opacity: enter,
    }}>
      {page.words.map((w, i) => {
        const active = t >= w.start && (i === page.words.length - 1 || t < page.words[i + 1].start);
        const key = emphasized.has(w);
        const pop = spring({ frame: frame - w.start * fps, fps, config: { damping: 10, stiffness: 260, mass: 0.5 } });
        return (
          <span key={i} style={{
            display: "inline-block", fontFamily: FONT, fontSize: key ? 102 : 88, fontWeight: 900, lineHeight: 1.2,
            // Từ đang đọc: vàng; từ thuộc từ khóa: xanh ngọc, to hơn và giữ màu cả khi không đọc tới
            color: active ? HILITE : key ? KEYWORD_COLOR : "#ffffff",
            WebkitTextStroke: "14px #000", paintOrder: "stroke fill",
            textShadow: key ? `0 8px 24px rgba(0,0,0,0.55), 0 0 28px ${KEYWORD_COLOR}66` : "0 8px 24px rgba(0,0,0,0.55)",
            transform: `scale(${active ? 1 + 0.12 * Math.min(pop, 1.2) : 1}) rotate(${key && active ? -3 : 0}deg)`,
          }}>
            {w.text}
          </span>
        );
      })}
    </div>
  );
};

// ---------- Tiêu đề cảnh: gõ máy, glitch với chủ đề công nghệ ----------

const TYPE_SPEED = 1.6; // ký tự mỗi frame

export const Heading = ({ text, enterDelay = HEADING_DELAY }: { text: string; enterDelay?: number }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const theme = useContext(ThemeContext);
  const enter = spring({ frame: frame - enterDelay, fps, config: { damping: 14, mass: 0.6 } });

  const chars = Array.from(text.normalize("NFC"));
  const local = frame - enterDelay;
  const typed = Math.max(0, Math.min(chars.length, Math.floor(local * TYPE_SPEED)));
  const doneAt = chars.length / TYPE_SPEED;
  // Con trỏ nhấp nháy khi đang gõ và thêm ~0.8 giây sau đó
  const showCursor = local >= 0 && local < doneAt + 24 && Math.floor(frame / 6) % 2 === 0;
  // Glitch: tách kênh màu đỏ/xanh lúc đang gõ, sau đó thỉnh thoảng giật lại
  const glitch = theme === "tech" && local >= 0 && (typed < chars.length || random(`hg-${Math.floor(frame / 3)}`) < 0.07);
  const gx = glitch ? (random(`hgx-${frame}`) - 0.5) * 14 : 0;

  return (
    <div style={{ position: "absolute", top: 170, left: 60, right: 60, display: "flex", justifyContent: "center" }}>
      <div style={{
        transform: `translateY(${(1 - enter) * -50}px) scale(${0.9 + 0.1 * enter}) translateX(${gx * 0.3}px)`,
        opacity: Math.min(enter, 1),
        padding: "18px 34px", borderRadius: 24, background: "rgba(15,18,32,0.85)",
        borderBottom: `8px solid ${ACCENT}`, color: "#fff", fontFamily: FONT,
        fontSize: 58, fontWeight: 800, lineHeight: 1.25, textAlign: "center",
      }}>
        <span style={{ textShadow: glitch ? `${gx}px 0 #ff2d6f, ${-gx}px 0 #22e4ff` : "none" }}>
          {chars.slice(0, typed).join("")}
        </span>
        {showCursor ? (
          <span style={{ display: "inline-block", width: 0, overflow: "visible", color: ACCENT }}>▍</span>
        ) : null}
        {/* Phần chưa gõ vẫn chiếm chỗ (trong suốt) để khung không co giãn khi gõ */}
        <span style={{ color: "transparent" }}>{chars.slice(typed).join("")}</span>
      </div>
    </div>
  );
};

// ---------- Khớp từ khóa với lời đọc ----------

export const normWord = (s: string) => s.normalize("NFC").toLowerCase().replace(/[.,;:!?"'()…“”«»]/g, "");

/**
 * Mốc thời gian (giây) từ đầu cảnh mà `keyword` được nói tới. Ưu tiên khớp nguyên cụm từ liên tiếp
 * (vd "hệ thần kinh"), nếu không có thì khớp chữ dài nhất của cụm, tránh dính vào chữ phổ biến như "là".
 */
export const findKeywordStart = (cues: Cue[], keyword: string): number | null => {
  const words = cues.flatMap((c) => c.words);
  const spoken = words.map((w) => normWord(w.text));
  const target = keyword.split(/\s+/).map(normWord).filter(Boolean);
  if (!target.length) return null;
  for (let i = 0; i + target.length <= spoken.length; i++) {
    if (target.every((tw, k) => spoken[i + k] === tw)) return words[i].start;
  }
  const longest = [...target].sort((a, b) => b.length - a.length)[0];
  if (longest.length < 3) return null;
  const j = spoken.indexOf(longest);
  return j >= 0 ? words[j].start : null;
};

/** Các từ trong lời đọc thuộc về một cụm từ khóa (khớp nguyên cụm liên tiếp). */
const keywordWords = (cues: Cue[], keywords?: string[] | null): Set<Word> => {
  const result = new Set<Word>();
  if (!keywords?.length) return result;
  const words = cues.flatMap((c) => c.words);
  const spoken = words.map((w) => normWord(w.text));
  for (const kw of keywords) {
    const target = kw.split(/\s+/).map(normWord).filter(Boolean);
    if (!target.length) continue;
    for (let i = 0; i + target.length <= spoken.length; i++) {
      if (target.every((tw, k) => spoken[i + k] === tw)) {
        for (let k = 0; k < target.length; k++) result.add(words[i + k]);
      }
    }
  }
  return result;
};

input.new_string:
  broll?: BrollBeat[] | null; // template "classic": clip stock đổi theo từng câu
  keywordEmojis?: string[] | null; // emoji cho từng keyword, cùng thứ tự
};

// Nhóm chủ đề: tech = mưa mã nhị phân + glitch, nature = lá rơi, còn lại = hạt sáng bokeh
export type Theme = "tech" | "nature" | "science" | "business" | "general";

export type SfxFiles = {
  whoosh?: string | null; pop?: string | null; tick?: string | null; impact?: string | null;
};

  sfx?: SfxFiles | null;
  theme?: Theme | null;
};

