import { useAudioData, visualizeAudio } from "@remotion/media-utils";
import React, { useContext } from "react";
import {
  AbsoluteFill, Audio, Easing, Sequence, interpolate, random, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import { ACCENT, CLAMP, FONT, HILITE, SfxContext, ThemeContext, findKeywordStart, normWord } from "./Shared";
import type { Cue } from "./types";

// ---------- Nền động: aurora + vệt sáng quét + hạt theo chủ đề + lưới chấm ----------

export type Palette = { base: [string, string]; glow: [string, string, string] };

export const PALETTES: Palette[] = [
  { base: ["#0b1240", "#2a0f5c"], glow: ["#6d8cff", "#b44dff", "#28d7ff"] },
  { base: ["#03141c", "#0b3342"], glow: ["#1fe3c2", "#2c8cff", "#7bffb0"] },
  { base: ["#22081f", "#4a0f28"], glow: ["#ff4d8d", "#ff9f43", "#c04dff"] },
  { base: ["#071f16", "#0f2f40"], glow: ["#4dffa6", "#2cc9ff", "#d4ff4d"] },
];

export const DARK_PALETTE: Palette = { base: ["#070a16", "#141a38"], glow: ["#3d5bff", "#7a3dff", "#1fb8ff"] };

type BgOptions = { sweep?: boolean; particles?: boolean; grid?: boolean; intensity?: number; audio?: string | null };

/**
 * Nền chuyển động liên tục. Chỉ dùng radial/linear-gradient (không dùng filter blur)
 * để render nhanh. Mọi chuyển động tính theo frame nên kết quả render ổn định.
 * Có `audio` thì các đốm sáng to và sáng lên theo âm lượng giọng đọc.
 */
export const AnimatedBackground = ({
  palette, seed = 0, sweep = true, particles = true, grid = false, intensity = 1, audio = null,
}: { palette: Palette; seed?: number } & BgOptions) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const theme = useContext(ThemeContext);
  const energy = useVoiceEnergy(audio);
  const t = frame / fps + seed * 7.3; // lệch pha giữa các cảnh cho đỡ giống nhau
  const [c1, c2] = palette.base;

  // 3 đốm sáng lớn trôi theo quỹ đạo Lissajous, tạo cảm giác màu "chảy"
  const blobs = palette.glow.map((color, i) => {
    const x = width * (0.5 + 0.38 * Math.sin(t * (0.35 + i * 0.12) + i * 2.1));
    const y = height * (0.45 + 0.3 * Math.cos(t * (0.27 + i * 0.09) + i * 1.3));
    const size = (1150 + 180 * Math.sin(t * 0.5 + i)) * (1 + 0.18 * energy);
    return `radial-gradient(circle ${size / 2}px at ${x}px ${y}px, ${color}${alpha((0.55 + 0.3 * energy) * intensity)}, transparent 70%)`;
  });

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <AbsoluteFill style={{ background: `linear-gradient(${150 + 25 * Math.sin(t * 0.3)}deg, ${c1}, ${c2})` }} />
      <AbsoluteFill style={{ background: blobs.join(","), filter: `hue-rotate(${18 * Math.sin(t * 0.25)}deg)` }} />
      {grid ? <DotGrid t={t} /> : null}
      {particles ? (
        theme === "tech" ? <BinaryRain t={t} seed={seed} />
          : theme === "nature" ? <Leaves t={t} seed={seed} />
            : <Bokeh t={t} seed={seed} />
      ) : null}
      {sweep ? <LightSweep t={t} /> : null}
      {/* Vignette giữ mắt người xem ở giữa khung và làm chữ nổi hơn */}
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, transparent 50%, rgba(0,0,0,0.55))" }} />
    </AbsoluteFill>
  );
};

export const alpha = (a: number) => Math.round(Math.max(0, Math.min(1, a)) * 255).toString(16).padStart(2, "0");

/** Âm lượng giọng đọc tại frame hiện tại, chuẩn hóa 0..1 (0 khi chưa nạp xong hoặc hết audio). */
const useVoiceEnergy = (audio: string | null): number => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const data = useAudioData(audio ? staticFile(audio) : "");
  if (!audio || !data || frame / fps >= data.durationInSeconds) return 0;
  const bins = visualizeAudio({ audioData: data, frame, fps, numberOfSamples: 16, smoothing: true });
  // Dải tần thấp-trung chứa phần lớn năng lượng giọng nói
  const e = (bins[0] + bins[1] + bins[2] + bins[3]) / 4;
  return Math.min(1, e * 4);
};

/** Vệt sáng chéo quét ngang màn hình, lặp mỗi 4.5 giây (kiểu ánh đèn lướt qua mặt kính). */
const LightSweep = ({ t }: { t: number }) => {
  const { width } = useVideoConfig();
  const period = 4.5;
  const p = (t % period) / period;
  const x = interpolate(p, [0, 0.55, 1], [-width, width * 1.2, width * 1.2]);
  return (
    <AbsoluteFill style={{ pointerEvents: "none", mixBlendMode: "screen" }}>
      <div style={{
        position: "absolute", top: -400, bottom: -400, width: 520, left: x,
        transform: "rotate(18deg)",
        background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.10) 40%, rgba(255,255,255,0.22) 50%, rgba(255,255,255,0.10) 60%, transparent)",
      }} />
    </AbsoluteFill>
  );
};

/** Vị trí rơi/bay lặp vòng trong khoảng [-100, height+100]. */
const wrapY = (y: number, height: number) => ((y % (height + 200)) + height + 200) % (height + 200) - 100;

/** Hạt sáng nhỏ bay lên, nhấp nháy. Vị trí sinh bằng random(seed) nên mỗi lần render đều giống nhau. */
const Bokeh = ({ t, seed }: { t: number; seed: number }) => {
  const { width, height } = useVideoConfig();
  const dots = Array.from({ length: 28 }, (_, i) => {
    const r = (k: string) => random(`bokeh-${seed}-${i}-${k}`);
    const size = 6 + r("s") * 22;
    const y = wrapY(r("y") * (height + 200) - t * (30 + r("v") * 70), height);
    const x = r("x") * width + 30 * Math.sin(t * (0.5 + r("w")) + i);
    const twinkle = 0.25 + 0.45 * (0.5 + 0.5 * Math.sin(t * (1 + r("f") * 2) + i));
    return (
      <div key={i} style={{
        position: "absolute", left: x, top: y, width: size, height: size, borderRadius: "50%",
        background: "radial-gradient(circle, rgba(255,255,255,0.95), rgba(255,255,255,0) 70%)",
        opacity: twinkle,
      }} />
    );
  });
  return <AbsoluteFill>{dots}</AbsoluteFill>;
};

/** Chủ đề công nghệ: các cột 0/1 rơi kiểu "Matrix", chữ đầu cột sáng nhất. */
const BinaryRain = ({ t, seed }: { t: number; seed: number }) => {
  const { width, height } = useVideoConfig();
  const cols = 16;
  const rows = 12;
  const cell = 46;
  const columns = Array.from({ length: cols }, (_, c) => {
    const r = (k: string) => random(`bin-${seed}-${c}-${k}`);
    const headY = wrapY(r("y") * (height + 200) + t * (120 + r("v") * 160), height);
    const x = (c + 0.5) * (width / cols) - 12;
    return Array.from({ length: rows }, (_, k) => {
      const y = headY - k * cell;
      if (y < -60 || y > height + 60) return null;
      const bit = random(`bit-${seed}-${c}-${k}-${Math.floor(t * 8)}`) < 0.5 ? "0" : "1";
      return (
        <div key={`${c}-${k}`} style={{
          position: "absolute", left: x, top: y, fontFamily: "Consolas, monospace", fontSize: 34, fontWeight: 700,
          color: k === 0 ? "#d9fff4" : "#39ffb4", opacity: (k === 0 ? 0.55 : 0.32) * (1 - k / rows),
        }}>
          {bit}
        </div>
      );
    });
  });
  return <AbsoluteFill>{columns}</AbsoluteFill>;
};

/** Chủ đề thiên nhiên: lá rơi lắc lư và xoay (vẽ bằng CSS, không phụ thuộc font emoji). */
const Leaves = ({ t, seed }: { t: number; seed: number }) => {
  const { width, height } = useVideoConfig();
  const colors = ["#7ed957", "#b5e655", "#f2b33d", "#e0773a"];
  const leaves = Array.from({ length: 16 }, (_, i) => {
    const r = (k: string) => random(`leaf-${seed}-${i}-${k}`);
    const size = 26 + r("s") * 30;
    const y = wrapY(r("y") * (height + 200) + t * (60 + r("v") * 80), height);
    const x = r("x") * width + 70 * Math.sin(t * (0.6 + r("w")) + i);
    const rot = 360 * r("r") + t * (40 + 60 * r("rv"));
    return (
      <div key={i} style={{
        position: "absolute", left: x, top: y, width: size, height: size * 0.6,
        borderRadius: "0 100% 0 100%", background: colors[i % colors.length], opacity: 0.55,
        transform: `rotate(${rot}deg) scaleX(${Math.cos(t * 2 + i)})`,
      }} />
    );
  });
  return <AbsoluteFill>{leaves}</AbsoluteFill>;
};

/** Lưới chấm mờ trôi chậm, hợp với phong cách "công nghệ" của template flow. */
const DotGrid = ({ t }: { t: number }) => (
  <AbsoluteFill style={{
    backgroundImage: "radial-gradient(rgba(255,255,255,0.10) 2px, transparent 2.5px)",
    backgroundSize: "64px 64px",
    backgroundPosition: `${(t * 12) % 64}px ${(t * 20) % 64}px`,
  }} />
);

// ---------- Nhấn mạnh: rung camera + flash trắng + tiếng "bùm" ----------

const PUNCH_LEN = 12;

/** Rung khung hình và chớp trắng tại các frame `triggers` (tính trong cảnh). */
export const Punch = ({ triggers, children }: { triggers: number[]; children: React.ReactNode }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const sfx = useContext(SfxContext);
  const active = triggers.find((f) => frame >= f && frame < f + PUNCH_LEN);
  const local = active != null ? frame - active : PUNCH_LEN;
  const decay = 1 - local / PUNCH_LEN;
  const dx = active != null ? (random(`sx-${frame}`) - 0.5) * 36 * decay : 0;
  const dy = active != null ? (random(`sy-${frame}`) - 0.5) * 36 * decay : 0;
  const zoom = active != null ? 1 + 0.05 * decay : 1;
  const flash = interpolate(local, [0, 1, 7], [0.75, 0.6, 0], CLAMP);

  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ transform: `translate(${dx}px, ${dy}px) scale(${zoom})` }}>{children}</AbsoluteFill>
      {flash > 0 ? <AbsoluteFill style={{ background: "#fff", opacity: flash }} /> : null}
      {sfx?.impact ? triggers.map((f, i) => (
        <Sequence key={i} from={f} durationInFrames={fps}>
          <Audio src={staticFile(sfx.impact!)} volume={0.55} />
        </Sequence>
      )) : null}
    </AbsoluteFill>
  );
};

/** Mốc (giây) con số `stat` được đọc: khớp nguyên cụm, không thì tìm từ có chứa phần số. */
export const findStatStart = (cues: Cue[], stat: string): number | null => {
  const direct = findKeywordStart(cues, stat);
  if (direct != null) return direct;
  const digits = stat.match(/\d+(?:[.,]\d+)?/)?.[0];
  if (!digits) return null;
  const w = cues.flatMap((c) => c.words).find((x) => normWord(x.text).includes(digits));
  return w ? w.start : null;
};

// ---------- Con số chạy từ 0 lên giá trị thật ----------

type ParsedStat = { prefix: string; value: number; decimals: number; sep: string; suffix: string; thousands: string | null };

/** "90%" -> 90, "1,5 tỷ" -> 1.5 (dấu phẩy thập phân), "10.000" -> 10000 (dấu chấm phân cách nghìn). */
const parseStat = (stat: string): ParsedStat | null => {
  const m = stat.match(/^(.*?)(\d+(?:[.,]\d+)*)(.*)$/);
  if (!m) return null;
  const [, prefix, num, suffix] = m;
  const thousandsMatch = num.match(/^\d{1,3}(([.,])\d{3})+$/);
  if (thousandsMatch) {
    const sep = thousandsMatch[2];
    return { prefix, value: Number(num.split(sep).join("")), decimals: 0, sep: "", suffix, thousands: sep };
  }
  const dec = num.match(/^(\d+)([.,])(\d+)$/);
  if (dec) return { prefix, value: Number(`${dec[1]}.${dec[3]}`), decimals: dec[3].length, sep: dec[2], suffix, thousands: null };
  return { prefix, value: Number(num), decimals: 0, sep: "", suffix, thousands: null };
};

const formatStat = (p: ParsedStat, v: number) => {
  let s = v.toFixed(p.decimals);
  if (p.decimals) s = s.replace(".", p.sep);
  if (p.thousands) s = Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, p.thousands);
  return `${p.prefix}${s}${p.suffix}`;
};

const COUNT_FRAMES = 26;

/** Con số nổi bật: bật vào, đếm từ 0 lên đúng lúc được đọc tới, có tiếng tick và nhịp "thở". */
export const StatCounter = ({ stat, cues, top, fontSize = 150 }: {
  stat?: string | null; cues: Cue[]; top: number; fontSize?: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const sfx = useContext(SfxContext);
  if (!stat) return null;
  const s = findStatStart(cues, stat);
  const start = s != null ? Math.round(s * fps) : 14;
  const local = frame - start;
  if (local < -2) return null;

  const parsed = parseStat(stat);
  const p = interpolate(local, [0, COUNT_FRAMES], [0, 1], { ...CLAMP, easing: Easing.out(Easing.cubic) });
  const text = parsed && Number.isFinite(parsed.value) ? formatStat(parsed, parsed.value * p) : stat;
  const enter = spring({ frame: local, fps, config: { damping: 12, mass: 0.6 } });
  const done = local >= COUNT_FRAMES;
  const pulse = done ? 1 + 0.03 * Math.sin(frame / 8) : 1;
  // Chốt số: bật nhẹ một cái khi đếm xong
  const land = interpolate(local, [COUNT_FRAMES, COUNT_FRAMES + 4, COUNT_FRAMES + 10], [1, 1.12, 1], CLAMP);

  return (
    <>
      <div style={{
        position: "absolute", top, left: 0, right: 0, textAlign: "center",
        fontFamily: FONT, fontSize, fontWeight: 900, color: HILITE, fontVariantNumeric: "tabular-nums",
        WebkitTextStroke: "10px #000", paintOrder: "stroke fill",
        textShadow: `0 8px 28px rgba(0,0,0,0.45), 0 0 ${30 + 20 * Math.sin(frame / 8)}px ${HILITE}88`,
        transform: `scale(${Math.max(0, enter) * pulse * land})`, opacity: Math.min(Math.max(enter, 0), 1),
      }}>
        {text}
      </div>
      {sfx?.tick && parsed ? Array.from({ length: Math.floor(COUNT_FRAMES / 3) }, (_, i) => (
        <Sequence key={i} from={Math.max(0, start + i * 3)} durationInFrames={6}>
          <Audio src={staticFile(sfx.tick!)} volume={0.22} />
        </Sequence>
      )) : null}
    </>
  );
};

// ---------- Chip từ khóa dạng nút bấm ----------

const CHIP_COLORS = [ACCENT, HILITE, "#4dffc3", "#ff6fb1"];

/**
 * Mỗi từ khóa là một "nút" bật ra đúng lúc được đọc tới: nảy vào, nhấn xuống như bị bấm,
 * có vòng sóng lan ra, vệt sáng lướt qua mặt nút và tiếng "pop". Nút đã hiện thì giữ lại tới hết cảnh.
 */
export const KeywordChips = ({ keywords, emojis, cues, frames, top, fontSize = 60 }: {
  keywords?: string[] | null; emojis?: string[] | null; cues: Cue[]; frames: number; top: number; fontSize?: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const sfx = useContext(SfxContext);
  const list = (keywords ?? []).map((k, i) => ({ text: k.trim(), emoji: emojis?.[i]?.trim() || null }))
    .filter((k) => k.text).slice(0, 4);
  if (!list.length) return null;

  // Không tìm thấy từ khóa trong lời đọc thì rải đều trong cảnh
  const triggers = list.map((kw, i) => {
    const s = findKeywordStart(cues, kw.text);
    return s != null ? Math.round(s * fps) : Math.round((frames * (i + 1)) / (list.length + 1));
  });

  return (
    <>
      <div style={{
        position: "absolute", top, left: 50, right: 50,
        display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "28px 26px",
      }}>
        {list.map((kw, i) => (
          <Chip key={i} text={kw.text} emoji={kw.emoji} local={frame - triggers[i]}
            color={CHIP_COLORS[i % CHIP_COLORS.length]} fontSize={fontSize} />
        ))}
      </div>
      {sfx?.pop ? triggers.map((f, i) => (
        <Sequence key={i} from={Math.max(0, f)} durationInFrames={Math.round(fps / 2)}>
          <Audio src={staticFile(sfx.pop!)} volume={0.4} />
        </Sequence>
      )) : null}
    </>
  );
};

const Chip = ({ text, emoji, local, color, fontSize }: {
  text: string; emoji: string | null; local: number; color: string; fontSize: number;
}) => {
  const { fps } = useVideoConfig();
  // Vẫn render khi chưa tới lượt (opacity 0) để các nút không nhảy vị trí khi nút mới xuất hiện
  const visible = local >= 0;
  const enter = visible ? spring({ frame: local, fps, config: { damping: 11, mass: 0.6, stiffness: 170 } }) : 0;
  const press = interpolate(local, [9, 13, 20], [1, 0.9, 1], CLAMP); // nhấn xuống rồi bật lên
  const shine = interpolate(local, [6, 24], [-120, 220], CLAMP); // vệt sáng lướt qua mặt nút (%)
  const ripple = interpolate(local, [11, 32], [0, 1], CLAMP);
  // Sáng rực lúc vừa được đọc, sau ~1 giây dịu lại thành nút "kính" nhưng vẫn phát sáng nhẹ
  const hot = interpolate(local, [0, 6, fps * 1.1, fps * 1.6], [0, 1, 1, 0], CLAMP);
  const breathe = 0.5 + 0.5 * Math.sin(local / 9);
  // Emoji lắc nhẹ khi vừa hiện
  const wiggle = interpolate(local, [4, 10, 16, 22], [0, -14, 10, 0], CLAMP);

  return (
    <div style={{
      position: "relative", opacity: Math.min(enter, 1),
      transform: `translateY(${(1 - enter) * 60}px) scale(${(0.6 + 0.4 * enter) * press})`,
    }}>
      {visible && ripple > 0 && ripple < 1 ? (
        <div style={{
          position: "absolute", inset: 0, borderRadius: 999, border: `4px solid ${color}`,
          transform: `scale(${1 + 0.45 * ripple})`, opacity: 1 - ripple,
        }} />
      ) : null}
      <div style={{
        position: "relative", overflow: "hidden", display: "flex", alignItems: "center", gap: 18,
        padding: "20px 40px 22px 30px", borderRadius: 999,
        background: `linear-gradient(135deg, rgba(12,16,34,${0.78 - 0.25 * hot}), rgba(12,16,34,0.62)), ${color}`,
        border: `4px solid ${color}`,
        boxShadow: `0 10px 30px rgba(0,0,0,0.45), 0 0 ${18 + 30 * hot + 10 * breathe}px ${color}${alpha(0.55 + 0.3 * hot)}`,
        fontFamily: FONT, fontSize, fontWeight: 800, color: "#fff", lineHeight: 1.15, whiteSpace: "nowrap",
      }}>
        {emoji ? (
          <span style={{ fontSize: fontSize * 0.95, lineHeight: 1, transform: `rotate(${wiggle}deg)`, display: "inline-block" }}>
            {emoji}
          </span>
        ) : (
          <span style={{
            width: fontSize * 0.42, height: fontSize * 0.42, borderRadius: "50%", flexShrink: 0,
            background: color, boxShadow: `0 0 ${12 + 12 * breathe}px ${color}`,
          }} />
        )}
        {text}
        <span style={{
          position: "absolute", top: 0, bottom: 0, left: `${shine}%`, width: "45%",
          transform: "skewX(-20deg)",
          background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.45), transparent)",
        }} />
      </div>
    </div>
  );
};

