1	import { loadFont } from "@remotion/google-fonts/BeVietnamPro";
2	import React, { useContext } from "react";
3	import { AbsoluteFill, Img, interpolate, random, spring, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
4	import type { Cue, SceneData, SfxFiles, Theme, Word } from "./types";
5	
6	export const FPS = 30;
7	// Khung dọc 9:16 cho Shorts/Reels
8	export const WIDTH = 1080;
9	export const HEIGHT = 1920;
10	// Số frame hai cảnh chồng lên nhau khi chuyển cảnh; khớp SCENE_PADDING_SEC (0.4s) bên Python
11	// nên giọng đọc cảnh trước đã dứt trước khi cảnh sau bắt đầu.
12	export const TRANSITION = 12;
13	// Intro (tiêu đề) và outro (kêu gọi follow), tính bằng frame. INTRO phải khớp INTRO_SEC trong app/config.py
14	export const INTRO = 36;
15	export const OUTRO = 90;
16	// Frame heading bắt đầu hiện (sau khi transition gần xong), SFX "pop" phát cùng lúc
17	export const HEADING_DELAY = 10;
18	export const ACCENT = "#6d8cff";
19	export const HILITE = "#ffe14d";
20	export const KEYWORD_COLOR = "#4dffc3";
21	// Vùng an toàn: dưới ~y=1570 bị UI của Shorts/Reels (caption, nút) che nên đặt phụ đề phía trên
22	export const SUBTITLE_TOP = 1180;
23	
24	const { fontFamily } = loadFont("normal", {
25	  weights: ["600", "800", "900"],
26	  subsets: ["vietnamese", "latin", "latin-ext"],
27	});
28	// Font emoji hệ thống (Windows: Segoe UI Emoji) cho icon cạnh chip từ khóa
29	export const FONT = `"${fontFamily}", "Segoe UI", Arial, "Segoe UI Emoji", "Noto Color Emoji", sans-serif`;
30	
31	export const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
32	
33	// Cho các thành phần bên trong cảnh (vd chip từ khóa) tự phát SFX mà không phải truyền props qua nhiều lớp
34	export const SfxContext = React.createContext<SfxFiles | null>(null);
35	// Nhóm chủ đề của video: quyết định kiểu hạt nền và hiệu ứng glitch
36	export const ThemeContext = React.createContext<Theme>("general");
37	
38	export const sceneFrames = (scene: SceneData) => Math.max(1, Math.round(scene.duration * FPS));
39	
40	// Transition chồng cảnh nhưng mỗi đoạn (trừ đoạn cuối) được kéo dài bù lại, nên tổng không đổi
41	export const totalFrames = (scenes: SceneData[]) =>
42	  INTRO + scenes.reduce((s, sc) => s + sceneFrames(sc), 0) + OUTRO;
43	
44	// ---------- Ảnh nền có chuyển động ----------
45	
46	/** Ken Burns với 4 kiểu chuyển động xoay vòng theo index: zoom vào, zoom ra, pan ngang, pan dọc. */
47	export const KenBurns = ({ src, index, frames }: { src: string; index: number; frames: number }) => {
48	  const frame = useCurrentFrame();
49	  const p = interpolate(frame, [0, frames + TRANSITION], [0, 1], CLAMP);
50	  const transforms = [
51	    `scale(${1 + 0.15 * p})`,
52	    `scale(${1.15 - 0.15 * p})`,
53	    `scale(1.15) translateX(${4 - 8 * p}%)`,
54	    `scale(1.15) translateY(${4 - 8 * p}%)`,
55	  ];
56	  return (
57	    <AbsoluteFill style={{ transform: transforms[index % transforms.length] }}>
58	      <Img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
59	    </AbsoluteFill>
60	  );
61	};
62	
63	// ---------- Phụ đề kiểu TikTok ----------
64	
65	type Page = { start: number; end: number; words: Word[] };
66	
67	/** Chia mỗi dòng phụ đề thành các "trang" 1-3 từ, ngắt thêm sau dấu phẩy. */
68	const toPages = (cues: Cue[], maxWords = 3): Page[] => {
69	  const pages: Page[] = [];
70	  for (const cue of cues) {
71	    let current: Word[] = [];
72	    const flush = () => {
73	      if (current.length) pages.push({ start: current[0].start, end: current[current.length - 1].end, words: current });
74	      current = [];
75	    };
76	    for (const w of cue.words) {
77	      current.push(w);
78	      if (current.length >= maxWords || /[,;:]$/.test(w.text)) flush();
79	    }
80	    flush();
81	  }
82	  return pages;
83	};
84	
85	export const Subtitles = ({ cues, keywords, top = SUBTITLE_TOP }: {
86	  cues: Cue[]; keywords?: string[] | null; top?: number;
87	}) => {
88	  const frame = useCurrentFrame();
89	  const { fps } = useVideoConfig();
90	  const t = frame / fps;
91	  const pages = toPages(cues);
92	  let idx = -1;
93	  for (let i = 0; i < pages.length; i++) if (pages[i].start <= t) idx = i;
94	  if (idx < 0) return null;
95	  const page = pages[idx];
96	  const next = pages[idx + 1];
97	  // Giữ trang tới khi trang sau bắt đầu (nếu gần), tránh phụ đề nhấp nháy giữa các từ
98	  const until = next && next.start - page.end < 0.6 ? next.start : page.end + 0.25;
99	  if (t >= until) return null;
100	
101	  const emphasized = keywordWords(cues, keywords);
102	  const enter = spring({ frame: frame - page.start * fps, fps, config: { damping: 200, stiffness: 300 } });
103	
104	  return (
105	    <div style={{
106	      position: "absolute", top, left: 60, right: 60,
107	      display: "flex", flexWrap: "wrap", justifyContent: "center", alignItems: "baseline", gap: "0 34px",
108	      transform: `scale(${0.8 + 0.2 * enter}) translateY(${(1 - enter) * 30}px)`,
109	      opacity: enter,
110	    }}>
111	      {page.words.map((w, i) => {
112	        const active = t >= w.start && (i === page.words.length - 1 || t < page.words[i + 1].start);
113	        const key = emphasized.has(w);
114	        const pop = spring({ frame: frame - w.start * fps, fps, config: { damping: 10, stiffness: 260, mass: 0.5 } });
115	        return (
116	          <span key={i} style={{
117	            display: "inline-block", fontFamily: FONT, fontSize: key ? 102 : 88, fontWeight: 900, lineHeight: 1.2,
118	            // Từ đang đọc: vàng; từ thuộc từ khóa: xanh ngọc, to hơn và giữ màu cả khi không đọc tới
119	            color: active ? HILITE : key ? KEYWORD_COLOR : "#ffffff",
120	            WebkitTextStroke: "14px #000", paintOrder: "stroke fill",
121	            textShadow: key ? `0 8px 24px rgba(0,0,0,0.55), 0 0 28px ${KEYWORD_COLOR}66` : "0 8px 24px rgba(0,0,0,0.55)",
122	            transform: `scale(${active ? 1 + 0.12 * Math.min(pop, 1.2) : 1}) rotate(${key && active ? -3 : 0}deg)`,
123	          }}>
124	            {w.text}
125	          </span>
126	        );
127	      })}
128	    </div>
129	  );
130	};
131	
132	// ---------- Tiêu đề cảnh: gõ máy, glitch với chủ đề công nghệ ----------
133	
134	const TYPE_SPEED = 1.6; // ký tự mỗi frame
135	
136	export const Heading = ({ text, enterDelay = HEADING_DELAY }: { text: string; enterDelay?: number }) => {
137	  const frame = useCurrentFrame();
138	  const { fps } = useVideoConfig();
139	  const theme = useContext(ThemeContext);
140	  const enter = spring({ frame: frame - enterDelay, fps, config: { damping: 14, mass: 0.6 } });
141	
142	  const chars = Array.from(text.normalize("NFC"));
143	  const local = frame - enterDelay;
144	  const typed = Math.max(0, Math.min(chars.length, Math.floor(local * TYPE_SPEED)));
145	  const doneAt = chars.length / TYPE_SPEED;
146	  // Con trỏ nhấp nháy khi đang gõ và thêm ~0.8 giây sau đó
147	  const showCursor = local >= 0 && local < doneAt + 24 && Math.floor(frame / 6) % 2 === 0;
148	  // Glitch: tách kênh màu đỏ/xanh lúc đang gõ, sau đó thỉnh thoảng giật lại
149	  const glitch = theme === "tech" && local >= 0 && (typed < chars.length || random(`hg-${Math.floor(frame / 3)}`) < 0.07);
150	  const gx = glitch ? (random(`hgx-${frame}`) - 0.5) * 14 : 0;
151	
152	  return (
153	    <div style={{ position: "absolute", top: 170, left: 60, right: 60, display: "flex", justifyContent: "center" }}>
154	      <div style={{
155	        transform: `translateY(${(1 - enter) * -50}px) scale(${0.9 + 0.1 * enter}) translateX(${gx * 0.3}px)`,
156	        opacity: Math.min(enter, 1),
157	        padding: "18px 34px", borderRadius: 24, background: "rgba(15,18,32,0.85)",
158	        borderBottom: `8px solid ${ACCENT}`, color: "#fff", fontFamily: FONT,
159	        fontSize: 58, fontWeight: 800, lineHeight: 1.25, textAlign: "center",
160	      }}>
161	        <span style={{ textShadow: glitch ? `${gx}px 0 #ff2d6f, ${-gx}px 0 #22e4ff` : "none" }}>
162	          {chars.slice(0, typed).join("")}
163	        </span>
164	        {showCursor ? (
165	          <span style={{ display: "inline-block", width: 0, overflow: "visible", color: ACCENT }}>▍</span>
166	        ) : null}
167	        {/* Phần chưa gõ vẫn chiếm chỗ (trong suốt) để khung không co giãn khi gõ */}
168	        <span style={{ color: "transparent" }}>{chars.slice(typed).join("")}</span>
169	      </div>
170	    </div>
171	  );
172	};
173	
174	// ---------- Khớp từ khóa với lời đọc ----------
175	
176	export const normWord = (s: string) => s.normalize("NFC").toLowerCase().replace(/[.,;:!?"'()…“”«»]/g, "");
177	
178	/**
179	 * Mốc thời gian (giây) từ đầu cảnh mà `keyword` được nói tới. Ưu tiên khớp nguyên cụm từ liên tiếp
180	 * (vd "hệ thần kinh"), nếu không có thì khớp chữ dài nhất của cụm, tránh dính vào chữ phổ biến như "là".
181	 */
182	export const findKeywordStart = (cues: Cue[], keyword: string): number | null => {
183	  const words = cues.flatMap((c) => c.words);
184	  const spoken = words.map((w) => normWord(w.text));
185	  const target = keyword.split(/\s+/).map(normWord).filter(Boolean);
186	  if (!target.length) return null;
187	  for (let i = 0; i + target.length <= spoken.length; i++) {
188	    if (target.every((tw, k) => spoken[i + k] === tw)) return words[i].start;
189	  }
190	  const longest = [...target].sort((a, b) => b.length - a.length)[0];
191	  if (longest.length < 3) return null;
192	  const j = spoken.indexOf(longest);
193	  return j >= 0 ? words[j].start : null;
194	};
195	
196	/** Các từ trong lời đọc thuộc về một cụm từ khóa (khớp nguyên cụm liên tiếp). */
197	const keywordWords = (cues: Cue[], keywords?: string[] | null): Set<Word> => {
198	  const result = new Set<Word>();
199	  if (!keywords?.length) return result;
200	  const words = cues.flatMap((c) => c.words);
201	  const spoken = words.map((w) => normWord(w.text));
202	  for (const kw of keywords) {
203	    const target = kw.split(/\s+/).map(normWord).filter(Boolean);
204	    if (!target.length) continue;
205	    for (let i = 0; i + target.length <= spoken.length; i++) {
206	      if (target.every((tw, k) => spoken[i + k] === tw)) {
207	        for (let k = 0; k < target.length; k++) result.add(words[i + k]);
208	      }
209	    }
210	  }
211	  return result;
212	};
