1	// Dữ liệu Python truyền sang qua props.json. Thời gian tính bằng giây, tương đối với đầu cảnh.
2	export type Word = { text: string; start: number; end: number };
3	export type Cue = { start: number; end: number; words: Word[] };
4	
5	export type DiagramNode = { id: string; label: string };
6	export type DiagramEdge = { from: string; to: string };
7	export type Diagram = { nodes: DiagramNode[]; edges: DiagramEdge[] };
8	
9	export type SceneData = {
10	  heading: string;
11	  image: string | null; // tên file trong public dir (thư mục job); null nếu template không dùng ảnh
12	  audio: string;
13	  duration: number;
14	  cues: Cue[];
15	  keywords?: string[] | null; // template "gradient": 1-3 từ khóa bay vào theo lời đọc
16	  stat?: string | null; // template "gradient": số liệu ngắn nổi bật
17	  diagram?: Diagram | null; // template "flow": sơ đồ luồng cho cảnh này
