20	  keywordEmojis?: string[] | null; // emoji cho từng keyword, cùng thứ tự
21	};
22	
23	// Nhóm chủ đề: tech = mưa mã nhị phân + glitch, nature = lá rơi, còn lại = hạt sáng bokeh
24	export type Theme = "tech" | "nature" | "science" | "business" | "general";
25	
26	// Một đoạn b-roll: phát `video` từ giây `start` tới `end` của cảnh. videoDuration = 0 nghĩa là không rõ.
27	export type BrollBeat = { start: number; end: number; video: string; videoDuration: number };
28	
29	export type SfxFiles = {
30	  whoosh?: string | null; pop?: string | null; tick?: string | null; impact?: string | null;
31	};
32	
33	export type VideoProps = {
34	  title: string;
35	  scenes: SceneData[];
36	  music?: string | null; // nhạc nền (tên file trong public dir), tự giảm âm lượng khi có giọng đọc
