1	import { useAudioData, visualizeAudio } from "@remotion/media-utils";
2	import React, { useContext } from "react";
3	import {
4	  AbsoluteFill, Audio, Easing, Sequence, interpolate, random, spring, staticFile, useCurrentFrame, useVideoConfig,
5	} from "remotion";
6	import { ACCENT, CLAMP, FONT, HILITE, SfxContext, ThemeContext, findKeywordStart, normWord } from "./Shared";
7	import type { Cue } from "./types";
8	
9	// ---------- Nền động: aurora + vệt sáng quét + hạt theo chủ đề + lưới chấm ----------
10	
11	export type Palette = { base: [string, string]; glow: [string, string, string] };
12	
13	export const PALETTES: Palette[] = [
14	  { base: ["#0b1240", "#2a0f5c"], glow: ["#6d8cff", "#b44dff", "#28d7ff"] },
15	  { base: ["#03141c", "#0b3342"], glow: ["#1fe3c2", "#2c8cff", "#7bffb0"] },
16	  { base: ["#22081f", "#4a0f28"], glow: ["#ff4d8d", "#ff9f43", "#c04dff"] },
17	  { base: ["#071f16", "#0f2f40"], glow: ["#4dffa6", "#2cc9ff", "#d4ff4d"] },
18	];
19	
20	export const DARK_PALETTE: Palette = { base: ["#070a16", "#141a38"], glow: ["#3d5bff", "#7a3dff", "#1fb8ff"] };
21	
22	type BgOptions = { sweep?: boolean; particles?: boolean; grid?: boolean; intensity?: number; audio?: string | null };
23	
24	/**
25	 * Nền chuyển động liên tục. Chỉ dùng radial/linear-gradient (không dùng filter blur)
26	 * để render nhanh. Mọi chuyển động tính theo frame nên kết quả render ổn định.
27	 * Có `audio` thì các đốm sáng to và sáng lên theo âm lượng giọng đọc.
28	 */
29	export const AnimatedBackground = ({
30	  palette, seed = 0, sweep = true, particles = true, grid = false, intensity = 1, audio = null,
31	}: { palette: Palette; seed?: number } & BgOptions) => {
32	  const frame = useCurrentFrame();
33	  const { fps, width, height } = useVideoConfig();
34	  const theme = useContext(ThemeContext);
35	  const energy = useVoiceEnergy(audio);
36	  const t = frame / fps + seed * 7.3; // lệch pha giữa các cảnh cho đỡ giống nhau
37	  const [c1, c2] = palette.base;
38	
39	  // 3 đốm sáng lớn trôi theo quỹ đạo Lissajous, tạo cảm giác màu "chảy"
40	  const blobs = palette.glow.map((color, i) => {
41	    const x = width * (0.5 + 0.38 * Math.sin(t * (0.35 + i * 0.12) + i * 2.1));
42	    const y = height * (0.45 + 0.3 * Math.cos(t * (0.27 + i * 0.09) + i * 1.3));
43	    const size = (1150 + 180 * Math.sin(t * 0.5 + i)) * (1 + 0.18 * energy);
44	    return `radial-gradient(circle ${size / 2}px at ${x}px ${y}px, ${color}${alpha((0.55 + 0.3 * energy) * intensity)}, transparent 70%)`;
45	  });
46	
47	  return (
48	    <AbsoluteFill style={{ overflow: "hidden" }}>
49	      <AbsoluteFill style={{ background: `linear-gradient(${150 + 25 * Math.sin(t * 0.3)}deg, ${c1}, ${c2})` }} />
50	      <AbsoluteFill style={{ background: blobs.join(","), filter: `hue-rotate(${18 * Math.sin(t * 0.25)}deg)` }} />
51	      {grid ? <DotGrid t={t} /> : null}
52	      {particles ? (
53	        theme === "tech" ? <BinaryRain t={t} seed={seed} />
54	          : theme === "nature" ? <Leaves t={t} seed={seed} />
55	            : <Bokeh t={t} seed={seed} />
56	      ) : null}
57	      {sweep ? <LightSweep t={t} /> : null}
58	      {/* Vignette giữ mắt người xem ở giữa khung và làm chữ nổi hơn */}
59	      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, transparent 50%, rgba(0,0,0,0.55))" }} />
60	    </AbsoluteFill>
61	  );
62	};
63	
64	export const alpha = (a: number) => Math.round(Math.max(0, Math.min(1, a)) * 255).toString(16).padStart(2, "0");
65	
66	/** Âm lượng giọng đọc tại frame hiện tại, chuẩn hóa 0..1 (0 khi chưa nạp xong hoặc hết audio). */
67	const useVoiceEnergy = (audio: string | null): number => {
68	  const frame = useCurrentFrame();
69	  const { fps } = useVideoConfig();
70	  const data = useAudioData(audio ? staticFile(audio) : "");
71	  if (!audio || !data || frame / fps >= data.durationInSeconds) return 0;
72	  const bins = visualizeAudio({ audioData: data, frame, fps, numberOfSamples: 16, smoothing: true });
73	  // Dải tần thấp-trung chứa phần lớn năng lượng giọng nói
74	  const e = (bins[0] + bins[1] + bins[2] + bins[3]) / 4;
75	  return Math.min(1, e * 4);
76	};
77	
78	/** Vệt sáng chéo quét ngang màn hình, lặp mỗi 4.5 giây (kiểu ánh đèn lướt qua mặt kính). */
79	const LightSweep = ({ t }: { t: number }) => {
80	  const { width } = useVideoConfig();
81	  const period = 4.5;
82	  const p = (t % period) / period;
83	  const x = interpolate(p, [0, 0.55, 1], [-width, width * 1.2, width * 1.2]);
84	  return (
85	    <AbsoluteFill style={{ pointerEvents: "none", mixBlendMode: "screen" }}>
86	      <div style={{
87	        position: "absolute", top: -400, bottom: -400, width: 520, left: x,
88	        transform: "rotate(18deg)",
89	        background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.10) 40%, rgba(255,255,255,0.22) 50%, rgba(255,255,255,0.10) 60%, transparent)",
90	      }} />
91	    </AbsoluteFill>
92	  );
93	};
94	
95	/** Vị trí rơi/bay lặp vòng trong khoảng [-100, height+100]. */
96	const wrapY = (y: number, height: number) => ((y % (height + 200)) + height + 200) % (height + 200) - 100;
97	
98	/** Hạt sáng nhỏ bay lên, nhấp nháy. Vị trí sinh bằng random(seed) nên mỗi lần render đều giống nhau. */
99	const Bokeh = ({ t, seed }: { t: number; seed: number }) => {
100	  const { width, height } = useVideoConfig();
101	  const dots = Array.from({ length: 28 }, (_, i) => {
102	    const r = (k: string) => random(`bokeh-${seed}-${i}-${k}`);
103	    const size = 6 + r("s") * 22;
104	    const y = wrapY(r("y") * (height + 200) - t * (30 + r("v") * 70), height);
105	    const x = r("x") * width + 30 * Math.sin(t * (0.5 + r("w")) + i);
106	    const twinkle = 0.25 + 0.45 * (0.5 + 0.5 * Math.sin(t * (1 + r("f") * 2) + i));
107	    return (
108	      <div key={i} style={{
109	        position: "absolute", left: x, top: y, width: size, height: size, borderRadius: "50%",
110	        background: "radial-gradient(circle, rgba(255,255,255,0.95), rgba(255,255,255,0) 70%)",
111	        opacity: twinkle,
112	      }} />
113	    );
114	  });
115	  return <AbsoluteFill>{dots}</AbsoluteFill>;
116	};
117	
118	/** Chủ đề công nghệ: các cột 0/1 rơi kiểu "Matrix", chữ đầu cột sáng nhất. */
119	const BinaryRain = ({ t, seed }: { t: number; seed: number }) => {
120	  const { width, height } = useVideoConfig();
121	  const cols = 16;
122	  const rows = 12;
123	  const cell = 46;
124	  const columns = Array.from({ length: cols }, (_, c) => {
125	    const r = (k: string) => random(`bin-${seed}-${c}-${k}`);
126	    const headY = wrapY(r("y") * (height + 200) + t * (120 + r("v") * 160), height);
127	    const x = (c + 0.5) * (width / cols) - 12;
128	    return Array.from({ length: rows }, (_, k) => {
129	      const y = headY - k * cell;
130	      if (y < -60 || y > height + 60) return null;
131	      const bit = random(`bit-${seed}-${c}-${k}-${Math.floor(t * 8)}`) < 0.5 ? "0" : "1";
132	      return (
133	        <div key={`${c}-${k}`} style={{
134	          position: "absolute", left: x, top: y, fontFamily: "Consolas, monospace", fontSize: 34, fontWeight: 700,
135	          color: k === 0 ? "#d9fff4" : "#39ffb4", opacity: (k === 0 ? 0.55 : 0.32) * (1 - k / rows),
136	        }}>
137	          {bit}
138	        </div>
139	      );
140	    });
141	  });
142	  return <AbsoluteFill>{columns}</AbsoluteFill>;
143	};
144	
145	/** Chủ đề thiên nhiên: lá rơi lắc lư và xoay (vẽ bằng CSS, không phụ thuộc font emoji). */
146	const Leaves = ({ t, seed }: { t: number; seed: number }) => {
147	  const { width, height } = useVideoConfig();
148	  const colors = ["#7ed957", "#b5e655", "#f2b33d", "#e0773a"];
149	  const leaves = Array.from({ length: 16 }, (_, i) => {
150	    const r = (k: string) => random(`leaf-${seed}-${i}-${k}`);
151	    const size = 26 + r("s") * 30;
152	    const y = wrapY(r("y") * (height + 200) + t * (60 + r("v") * 80), height);
153	    const x = r("x") * width + 70 * Math.sin(t * (0.6 + r("w")) + i);
154	    const rot = 360 * r("r") + t * (40 + 60 * r("rv"));
155	    return (
156	      <div key={i} style={{
157	        position: "absolute", left: x, top: y, width: size, height: size * 0.6,
158	        borderRadius: "0 100% 0 100%", background: colors[i % colors.length], opacity: 0.55,
159	        transform: `rotate(${rot}deg) scaleX(${Math.cos(t * 2 + i)})`,
160	      }} />
161	    );
162	  });
163	  return <AbsoluteFill>{leaves}</AbsoluteFill>;
164	};
165	
166	/** Lưới chấm mờ trôi chậm, hợp với phong cách "công nghệ" của template flow. */
167	const DotGrid = ({ t }: { t: number }) => (
168	  <AbsoluteFill style={{
169	    backgroundImage: "radial-gradient(rgba(255,255,255,0.10) 2px, transparent 2.5px)",
170	    backgroundSize: "64px 64px",
171	    backgroundPosition: `${(t * 12) % 64}px ${(t * 20) % 64}px`,
172	  }} />
173	);
174	
175	// ---------- Nhấn mạnh: rung camera + flash trắng + tiếng "bùm" ----------
176	
177	const PUNCH_LEN = 12;
178	
179	/** Rung khung hình và chớp trắng tại các frame `triggers` (tính trong cảnh). */
180	export const Punch = ({ triggers, children }: { triggers: number[]; children: React.ReactNode }) => {
181	  const frame = useCurrentFrame();
182	  const { fps } = useVideoConfig();
183	  const sfx = useContext(SfxContext);
184	  const active = triggers.find((f) => frame >= f && frame < f + PUNCH_LEN);
185	  const local = active != null ? frame - active : PUNCH_LEN;
186	  const decay = 1 - local / PUNCH_LEN;
187	  const dx = active != null ? (random(`sx-${frame}`) - 0.5) * 36 * decay : 0;
188	  const dy = active != null ? (random(`sy-${frame}`) - 0.5) * 36 * decay : 0;
189	  const zoom = active != null ? 1 + 0.05 * decay : 1;
190	  const flash = interpolate(local, [0, 1, 7], [0.75, 0.6, 0], CLAMP);
191	
192	  return (
193	    <AbsoluteFill>
194	      <AbsoluteFill style={{ transform: `translate(${dx}px, ${dy}px) scale(${zoom})` }}>{children}</AbsoluteFill>
195	      {flash > 0 ? <AbsoluteFill style={{ background: "#fff", opacity: flash }} /> : null}
196	      {sfx?.impact ? triggers.map((f, i) => (
197	        <Sequence key={i} from={f} durationInFrames={fps}>
198	          <Audio src={staticFile(sfx.impact!)} volume={0.55} />
199	        </Sequence>
200	      )) : null}
201	    </AbsoluteFill>
202	  );
203	};
204	
205	/** Mốc (giây) con số `stat` được đọc: khớp nguyên cụm, không thì tìm từ có chứa phần số. */
206	export const findStatStart = (cues: Cue[], stat: string): number | null => {
207	  const direct = findKeywordStart(cues, stat);
208	  if (direct != null) return direct;
209	  const digits = stat.match(/\d+(?:[.,]\d+)?/)?.[0];
210	  if (!digits) return null;
211	  const w = cues.flatMap((c) => c.words).find((x) => normWord(x.text).includes(digits));
212	  return w ? w.start : null;
213	};
214	
215	// ---------- Con số chạy từ 0 lên giá trị thật ----------
216	
217	type ParsedStat = { prefix: string; value: number; decimals: number; sep: string; suffix: string; thousands: string | null };
218	
219	/** "90%" -> 90, "1,5 tỷ" -> 1.5 (dấu phẩy thập phân), "10.000" -> 10000 (dấu chấm phân cách nghìn). */
220	const parseStat = (stat: string): ParsedStat | null => {
221	  const m = stat.match(/^(.*?)(\d+(?:[.,]\d+)*)(.*)$/);
222	  if (!m) return null;
223	  const [, prefix, num, suffix] = m;
224	  const thousandsMatch = num.match(/^\d{1,3}(([.,])\d{3})+$/);
225	  if (thousandsMatch) {
226	    const sep = thousandsMatch[2];
227	    return { prefix, value: Number(num.split(sep).join("")), decimals: 0, sep: "", suffix, thousands: sep };
228	  }
229	  const dec = num.match(/^(\d+)([.,])(\d+)$/);
230	  if (dec) return { prefix, value: Number(`${dec[1]}.${dec[3]}`), decimals: dec[3].length, sep: dec[2], suffix, thousands: null };
231	  return { prefix, value: Number(num), decimals: 0, sep: "", suffix, thousands: null };
232	};
233	
234	const formatStat = (p: ParsedStat, v: number) => {
235	  let s = v.toFixed(p.decimals);
236	  if (p.decimals) s = s.replace(".", p.sep);
237	  if (p.thousands) s = Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, p.thousands);
238	  return `${p.prefix}${s}${p.suffix}`;
239	};
240	
241	const COUNT_FRAMES = 26;
242	
243	/** Con số nổi bật: bật vào, đếm từ 0 lên đúng lúc được đọc tới, có tiếng tick và nhịp "thở". */
244	export const StatCounter = ({ stat, cues, top, fontSize = 150 }: {
245	  stat?: string | null; cues: Cue[]; top: number; fontSize?: number;
246	}) => {
247	  const frame = useCurrentFrame();
248	  const { fps } = useVideoConfig();
249	  const sfx = useContext(SfxContext);
250	  if (!stat) return null;
251	  const s = findStatStart(cues, stat);
252	  const start = s != null ? Math.round(s * fps) : 14;
253	  const local = frame - start;
254	  if (local < -2) return null;
255	
256	  const parsed = parseStat(stat);
257	  const p = interpolate(local, [0, COUNT_FRAMES], [0, 1], { ...CLAMP, easing: Easing.out(Easing.cubic) });
258	  const text = parsed && Number.isFinite(parsed.value) ? formatStat(parsed, parsed.value * p) : stat;
259	  const enter = spring({ frame: local, fps, config: { damping: 12, mass: 0.6 } });
260	  const done = local >= COUNT_FRAMES;
261	  const pulse = done ? 1 + 0.03 * Math.sin(frame / 8) : 1;
262	  // Chốt số: bật nhẹ một cái khi đếm xong
263	  const land = interpolate(local, [COUNT_FRAMES, COUNT_FRAMES + 4, COUNT_FRAMES + 10], [1, 1.12, 1], CLAMP);
264	
265	  return (
266	    <>
267	      <div style={{
268	        position: "absolute", top, left: 0, right: 0, textAlign: "center",
269	        fontFamily: FONT, fontSize, fontWeight: 900, color: HILITE, fontVariantNumeric: "tabular-nums",
270	        WebkitTextStroke: "10px #000", paintOrder: "stroke fill",
271	        textShadow: `0 8px 28px rgba(0,0,0,0.45), 0 0 ${30 + 20 * Math.sin(frame / 8)}px ${HILITE}88`,
272	        transform: `scale(${Math.max(0, enter) * pulse * land})`, opacity: Math.min(Math.max(enter, 0), 1),
273	      }}>
274	        {text}
275	      </div>
276	      {sfx?.tick && parsed ? Array.from({ length: Math.floor(COUNT_FRAMES / 3) }, (_, i) => (
277	        <Sequence key={i} from={Math.max(0, start + i * 3)} durationInFrames={6}>
278	          <Audio src={staticFile(sfx.tick!)} volume={0.22} />
279	        </Sequence>
280	      )) : null}
281	    </>
282	  );
283	};
284	
285	// ---------- Chip từ khóa dạng nút bấm ----------
286	
287	const CHIP_COLORS = [ACCENT, HILITE, "#4dffc3", "#ff6fb1"];
288	
289	/**
290	 * Mỗi từ khóa là một "nút" bật ra đúng lúc được đọc tới: nảy vào, nhấn xuống như bị bấm,
291	 * có vòng sóng lan ra, vệt sáng lướt qua mặt nút và tiếng "pop". Nút đã hiện thì giữ lại tới hết cảnh.
292	 */
293	export const KeywordChips = ({ keywords, emojis, cues, frames, top, fontSize = 60 }: {
294	  keywords?: string[] | null; emojis?: string[] | null; cues: Cue[]; frames: number; top: number; fontSize?: number;
295	}) => {
296	  const frame = useCurrentFrame();
297	  const { fps } = useVideoConfig();
298	  const sfx = useContext(SfxContext);
299	  const list = (keywords ?? []).map((k, i) => ({ text: k.trim(), emoji: emojis?.[i]?.trim() || null }))
300	    .filter((k) => k.text).slice(0, 4);
301	  if (!list.length) return null;
302	
303	  // Không tìm thấy từ khóa trong lời đọc thì rải đều trong cảnh
304	  const triggers = list.map((kw, i) => {
305	    const s = findKeywordStart(cues, kw.text);
306	    return s != null ? Math.round(s * fps) : Math.round((frames * (i + 1)) / (list.length + 1));
307	  });
308	
309	  return (
310	    <>
311	      <div style={{
312	        position: "absolute", top, left: 50, right: 50,
313	        display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "28px 26px",
314	      }}>
315	        {list.map((kw, i) => (
316	          <Chip key={i} text={kw.text} emoji={kw.emoji} local={frame - triggers[i]}
317	            color={CHIP_COLORS[i % CHIP_COLORS.length]} fontSize={fontSize} />
318	        ))}
319	      </div>
320	      {sfx?.pop ? triggers.map((f, i) => (
321	        <Sequence key={i} from={Math.max(0, f)} durationInFrames={Math.round(fps / 2)}>
322	          <Audio src={staticFile(sfx.pop!)} volume={0.4} />
323	        </Sequence>
324	      )) : null}
325	    </>
326	  );
327	};
328	
329	const Chip = ({ text, emoji, local, color, fontSize }: {
330	  text: string; emoji: string | null; local: number; color: string; fontSize: number;
331	}) => {
332	  const { fps } = useVideoConfig();
333	  // Vẫn render khi chưa tới lượt (opacity 0) để các nút không nhảy vị trí khi nút mới xuất hiện
334	  const visible = local >= 0;
335	  const enter = visible ? spring({ frame: local, fps, config: { damping: 11, mass: 0.6, stiffness: 170 } }) : 0;
336	  const press = interpolate(local, [9, 13, 20], [1, 0.9, 1], CLAMP); // nhấn xuống rồi bật lên
337	  const shine = interpolate(local, [6, 24], [-120, 220], CLAMP); // vệt sáng lướt qua mặt nút (%)
338	  const ripple = interpolate(local, [11, 32], [0, 1], CLAMP);
339	  // Sáng rực lúc vừa được đọc, sau ~1 giây dịu lại thành nút "kính" nhưng vẫn phát sáng nhẹ
340	  const hot = interpolate(local, [0, 6, fps * 1.1, fps * 1.6], [0, 1, 1, 0], CLAMP);
341	  const breathe = 0.5 + 0.5 * Math.sin(local / 9);
342	  // Emoji lắc nhẹ khi vừa hiện
343	  const wiggle = interpolate(local, [4, 10, 16, 22], [0, -14, 10, 0], CLAMP);
344	
345	  return (
346	    <div style={{
347	      position: "relative", opacity: Math.min(enter, 1),
348	      transform: `translateY(${(1 - enter) * 60}px) scale(${(0.6 + 0.4 * enter) * press})`,
349	    }}>
350	      {visible && ripple > 0 && ripple < 1 ? (
351	        <div style={{
352	          position: "absolute", inset: 0, borderRadius: 999, border: `4px solid ${color}`,
353	          transform: `scale(${1 + 0.45 * ripple})`, opacity: 1 - ripple,
354	        }} />
355	      ) : null}
356	      <div style={{
357	        position: "relative", overflow: "hidden", display: "flex", alignItems: "center", gap: 18,
358	        padding: "20px 40px 22px 30px", borderRadius: 999,
359	        background: `linear-gradient(135deg, rgba(12,16,34,${0.78 - 0.25 * hot}), rgba(12,16,34,0.62)), ${color}`,
360	        border: `4px solid ${color}`,
361	        boxShadow: `0 10px 30px rgba(0,0,0,0.45), 0 0 ${18 + 30 * hot + 10 * breathe}px ${color}${alpha(0.55 + 0.3 * hot)}`,
362	        fontFamily: FONT, fontSize, fontWeight: 800, color: "#fff", lineHeight: 1.15, whiteSpace: "nowrap",
363	      }}>
364	        {emoji ? (
365	          <span style={{ fontSize: fontSize * 0.95, lineHeight: 1, transform: `rotate(${wiggle}deg)`, display: "inline-block" }}>
366	            {emoji}
367	          </span>
368	        ) : (
369	          <span style={{
370	            width: fontSize * 0.42, height: fontSize * 0.42, borderRadius: "50%", flexShrink: 0,
371	            background: color, boxShadow: `0 0 ${12 + 12 * breathe}px ${color}`,
372	          }} />
373	        )}
374	        {text}
375	        <span style={{
376	          position: "absolute", top: 0, bottom: 0, left: `${shine}%`, width: "45%",
377	          transform: "skewX(-20deg)",
378	          background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.45), transparent)",
379	        }} />
380	      </div>
381	    </div>
382	  );
383	};
384

