import { TransitionSeries, springTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { slide } from "@remotion/transitions/slide";
import { wipe } from "@remotion/transitions/wipe";
import React from "react";
import {
  AbsoluteFill, Audio, Sequence, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig,
} from "remotion";
import { AnimatedBackground, PALETTES, Punch, findStatStart } from "./Effects";
import {
  ACCENT, CLAMP, FONT, FPS, HEADING_DELAY, HILITE, INTRO, OUTRO, SfxContext, TRANSITION, ThemeContext, sceneFrames,
} from "./Shared";
import type { SceneData, VideoProps } from "./types";

// ---------- Khung video: intro, các cảnh, outro, chuyển cảnh, nhạc nền, SFX ----------

const timing = springTiming({ config: { damping: 200 }, durationInFrames: TRANSITION });

// Gọi như hàm (không phải component) để TransitionSeries nhận đúng kiểu phần tử con
const transitionAt = (i: number) => {
  const key = `t${i}`;
  switch (i % 4) {
    case 1: return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-right" })} timing={timing} />;
    case 2: return <TransitionSeries.Transition key={key} presentation={wipe({ direction: "from-bottom" })} timing={timing} />;
    case 3: return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-bottom" })} timing={timing} />;
    default: return <TransitionSeries.Transition key={key} presentation={fade()} timing={timing} />;
  }
};

/** Frame (trong cảnh) cần "đập" mạnh: câu hook đầu video và lúc con số nổi bật được đọc. */
const punchTriggers = (scene: SceneData, index: number): number[] => {
  const result: number[] = [];
  if (index === 0) {
    const first = scene.cues[0]?.words[0]?.start;
    result.push(first != null ? Math.round(first * FPS) : HEADING_DELAY);
  }
  if (scene.stat) {
    const s = findStatStart(scene.cues, scene.stat);
    if (s != null) result.push(Math.round(s * FPS));
  }
  return result;
};

type ShellProps = VideoProps & {
  background: string;
  renderScene: (scene: SceneData, index: number, frames: number) => React.ReactNode;
};

export const VideoShell = ({ title, scenes, music, musicVolume, sfx, theme, background, renderScene }: ShellProps) => {
  const frames = scenes.map(sceneFrames);
  const starts: number[] = [];
  frames.reduce((acc, f) => { starts.push(acc); return acc + f; }, INTRO);
  const outroStart = INTRO + frames.reduce((a, b) => a + b, 0);

  // Mỗi đoạn (trừ outro) kéo dài thêm TRANSITION frame để chồng lên đoạn sau,
  // nhờ vậy đoạn i vẫn bắt đầu đúng ở starts[i] và tổng thời lượng không đổi.
  const items: React.ReactNode[] = [
    <TransitionSeries.Sequence key="intro" durationInFrames={INTRO + TRANSITION}>
      <Intro title={title} />
    </TransitionSeries.Sequence>,
  ];
  scenes.forEach((scene, i) => {
    items.push(transitionAt(i));
    items.push(
      <TransitionSeries.Sequence key={`s${i}`} durationInFrames={frames[i] + TRANSITION}>
        <Punch triggers={punchTriggers(scene, i)}>{renderScene(scene, i, frames[i])}</Punch>
      </TransitionSeries.Sequence>,
    );
  });
  items.push(transitionAt(scenes.length));
  items.push(
    <TransitionSeries.Sequence key="outro" durationInFrames={OUTRO}>
      <Outro />
    </TransitionSeries.Sequence>,
  );

  // Khoảng thời gian có giọng đọc (giây, tính từ đầu video) để giảm nhạc nền
  const speech = scenes
    .map((s, i) => s.cues.length
      ? [starts[i] / FPS + s.cues[0].start, starts[i] / FPS + s.cues[s.cues.length - 1].end] as const
      : null)
    .filter((x): x is readonly [number, number] => x !== null);

  return (
    <ThemeContext.Provider value={theme ?? "general"}>
      <SfxContext.Provider value={sfx ?? null}>
        <AbsoluteFill style={{ backgroundColor: background }}>
          <TransitionSeries>{items}</TransitionSeries>
          <Sequence from={INTRO} durationInFrames={outroStart - INTRO}>
            <ChapterBar scenes={scenes} frames={frames} />
          </Sequence>
          {music ? <BackgroundMusic src={music} volume={musicVolume ?? 0.18} speech={speech} /> : null}
          {sfx?.whoosh ? [...starts, outroStart].map((s, i) => (
            <Sequence key={`w${i}`} from={Math.max(0, s - 4)} durationInFrames={FPS}>
              <Audio src={staticFile(sfx.whoosh!)} volume={0.35} />
            </Sequence>
          )) : null}
          {sfx?.pop ? starts.map((s, i) => (
            <Sequence key={`p${i}`} from={s + HEADING_DELAY} durationInFrames={FPS / 2}>
              <Audio src={staticFile(sfx.pop!)} volume={0.3} />
            </Sequence>
          )) : null}
        </AbsoluteFill>
      </SfxContext.Provider>
    </ThemeContext.Provider>
  );
};

const BackgroundMusic = ({ src, volume, speech }: {
  src: string; volume: number; speech: (readonly [number, number])[];
}) => {
  const { fps, durationInFrames: total } = useVideoConfig();
  return (
    <Audio
      src={staticFile(src)}
      loop
      volume={(f) => {
        const t = f / fps;
        // Khoảng cách tới đoạn có giọng đọc gần nhất: đang đọc thì nhạc nhỏ, khoảng lặng thì to lên
        let d = Infinity;
        for (const [a, b] of speech) {
          if (t >= a && t <= b) { d = 0; break; }
          d = Math.min(d, t < a ? a - t : t - b);
        }
        const duck = interpolate(d, [0.1, 0.6], [1, 0], CLAMP);
        const fadeInOut = interpolate(
          f, [0, fps, Math.max(fps + 1, total - fps * 1.5), Math.max(fps + 2, total)], [0, 1, 1, 0], CLAMP,
        );
        return volume * (1 - 0.6 * duck) * fadeInOut;
      }}
    />
  );
};

// ---------- Thanh tiến độ chia chương ----------

/** Mỗi cảnh một đoạn, rộng theo thời lượng; kèm nhãn "2/5 · tên cảnh" hiện vài giây đầu mỗi cảnh. */
const ChapterBar = ({ scenes, frames }: { scenes: SceneData[]; frames: number[] }) => {
  const frame = useCurrentFrame();
  const total = frames.reduce((a, b) => a + b, 0);
  let acc = 0;
  let current = 0;
  const segs = frames.map((f, i) => {
    const from = acc;
    acc += f;
    if (frame >= from && frame < acc) current = i;
    return { from, f, fill: interpolate(frame, [from, from + f], [0, 1], CLAMP) };
  });
  const local = frame - segs[current].from;
  const label = interpolate(local, [4, 12, 75, 90], [0, 1, 1, 0], CLAMP);

  return (
    <>
      <div style={{ position: "absolute", top: 14, left: 24, right: 24, height: 10, display: "flex", gap: 8 }}>
        {segs.map((s, i) => (
          <div key={i} style={{
            flex: s.f / total, height: "100%", borderRadius: 5, overflow: "hidden", background: "rgba(255,255,255,0.22)",
          }}>
            <div style={{
              width: `${s.fill * 100}%`, height: "100%", background: i === current ? HILITE : ACCENT,
              boxShadow: i === current ? `0 0 12px ${HILITE}` : "none",
            }} />
          </div>
        ))}
      </div>
      <div style={{
        position: "absolute", top: 40, left: 24, opacity: label,
        transform: `translateY(${(1 - label) * -12}px)`,
        padding: "6px 16px", borderRadius: 12, background: "rgba(10,12,24,0.7)",
        fontFamily: FONT, fontSize: 28, fontWeight: 700, color: "#fff", whiteSpace: "nowrap",
        maxWidth: 900, overflow: "hidden", textOverflow: "ellipsis",
      }}>
        <span style={{ color: HILITE }}>{current + 1}/{scenes.length}</span> · {scenes[current].heading}
      </div>
    </>
  );
};

// ---------- Intro: tiêu đề video bật từng chữ ----------

const Intro = ({ title }: { title: string }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const words = title.split(/\s+/).filter(Boolean);
  const underline = interpolate(frame, [words.length * 3 + 4, words.length * 3 + 16], [0, 1], CLAMP);
