  const handIn = interpolate(frame, [20, 28, TAP_AT + 14, TAP_AT + 22], [0, 1, 1, 0], CLAMP);
  const press = interpolate(frame, [TAP_AT - 3, TAP_AT, TAP_AT + 6], [1, 0.88, 1], CLAMP);
  const ripple = interpolate(frame, [TAP_AT, TAP_AT + 20], [0, 1], CLAMP);
  const bell = tapped ? 18 * Math.sin((frame - TAP_AT) / 2) * Math.exp(-(frame - TAP_AT) / 14) : 0;

  return (
    <AbsoluteFill>
      <AnimatedBackground palette={PALETTES[2]} seed={77} />
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", gap: 60 }}>
        <div style={{
          fontFamily: FONT, fontSize: 84, fontWeight: 900, color: "#fff", textAlign: "center", lineHeight: 1.2,
          WebkitTextStroke: "10px #000", paintOrder: "stroke fill", padding: "0 60px",
          transform: `scale(${0.6 + 0.4 * text})`, opacity: Math.min(text, 1),
        }}>
          Thấy hay thì<br /><span style={{ color: HILITE }}>follow</span> để xem thêm nhé!
        </div>
        <div style={{ position: "relative", transform: `scale(${Math.max(0, btn) * press})`, opacity: Math.min(btn, 1) }}>
          {ripple > 0 && ripple < 1 ? (
            <div style={{
              position: "absolute", inset: 0, borderRadius: 999, border: "6px solid #fff",
              transform: `scale(${1 + 0.5 * ripple})`, opacity: 1 - ripple,
            }} />
          ) : null}
          <div style={{
            display: "flex", alignItems: "center", gap: 20, padding: "28px 56px", borderRadius: 999,
            background: tapped ? "#2a2f45" : "#ff2d55", color: "#fff",
            fontFamily: FONT, fontSize: 64, fontWeight: 900,
            boxShadow: tapped ? "0 10px 30px rgba(0,0,0,0.4)" : "0 10px 40px rgba(255,45,85,0.6)",
          }}>
            <span style={{ display: "inline-block", transform: `rotate(${bell}deg)` }}>{tapped ? "🔔" : "➕"}</span>
            {tapped ? "Đã follow ✓" : "Follow"}
          </div>
          <div style={{
            position: "absolute", left: handX, top: handY, fontSize: 110, opacity: handIn,
            transform: `scale(${tapped && frame < TAP_AT + 6 ? 0.9 : 1})`,
          }}>
            👆
          </div>
        </div>
      </AbsoluteFill>
      {sfx?.pop ? (
        <Sequence from={TAP_AT} durationInFrames={fps}>
          <Audio src={staticFile(sfx.pop)} volume={0.5} />
        </Sequence>
      ) : null}
    </AbsoluteFill>
  );
};

