import { AbsoluteFill, Audio, staticFile } from "remotion";
import { KeywordChips, PALETTES, StatCounter, VoiceBackground } from "./Effects";
import { Heading, Subtitles } from "./Shared";
import { VideoShell } from "./Shell";
import type { SceneData, VideoProps } from "./types";

export const GradientVideo = (props: VideoProps) => (
  <VideoShell
    {...props}
    background="#000"
    renderScene={(scene, i, frames) => <GradientScene scene={scene} index={i} frames={frames} />}
  />
);

const GradientScene = ({ scene, index, frames }: { scene: SceneData; index: number; frames: number }) => (
  <AbsoluteFill>
    <VoiceBackground audio={scene.audio} palette={PALETTES[index % PALETTES.length]} seed={index} />
    <Heading text={scene.heading} />
    <StatCounter stat={scene.stat} cues={scene.cues} top={360} />
    <KeywordChips keywords={scene.keywords} emojis={scene.keywordEmojis} cues={scene.cues} frames={frames}
      top={scene.stat ? 640 : 560} fontSize={64} />
    <Subtitles cues={scene.cues} keywords={scene.keywords} top={1320} />
    <Audio src={staticFile(scene.audio)} />
  </AbsoluteFill>
);

