input.content:
import { Composition } from "remotion";
import { ClassicVideo } from "./ClassicVideo";
import { GradientVideo } from "./GradientVideo";
import { FlowVideo } from "./FlowVideo";
import { MemeVideo } from "./MemeVideo";
import { FPS, HEIGHT, WIDTH, totalFrames } from "./Shared";
import type { VideoProps } from "./types";

const defaultProps: VideoProps = { title: "Xem trước", scenes: [] };

// Tổng = intro + các cảnh + outro (transition chồng cảnh nhưng đã được bù trong VideoShell)
const calculateMetadata = ({ props }: { props: VideoProps }) => ({
  durationInFrames: Math.max(totalFrames(props.scenes), 1),
});

const COMPOSITIONS = [
  { id: "ClassicVideo", component: ClassicVideo },
  { id: "GradientVideo", component: GradientVideo },
  { id: "FlowVideo", component: FlowVideo },
  { id: "MemeVideo", component: MemeVideo },
];

export const RemotionRoot = () => (
  <>
    {COMPOSITIONS.map(({ id, component }) => (
      <Composition
        key={id}
        id={id}
        component={component}
        fps={FPS}
        width={WIDTH}
        height={HEIGHT}
        durationInFrames={FPS * 5}
        defaultProps={defaultProps}
        calculateMetadata={calculateMetadata}
      />
    ))}
  </>
);

